const ACTIVE_WORKFLOW_STATUSES = new Set(["running", "pending"]);
const WORKFLOW_POLL_INTERVAL_MS = 8_000;
const TERMINAL_WORKFLOW_POLL_INTERVAL_MS = 30_000;
const LOG_POLL_INTERVAL_MS = 5_000;
const LOG_CLIENT_BUFFER_CHARS = 1_000_000;
const WORKFLOW_DETAIL_REQUEST_TIMEOUT_MS = 12_000;
const RUN_LEDGER_REQUEST_TIMEOUT_MS = 12_000;

class RequestTimeoutError extends Error {
	constructor(message: string) {
		super(message);
		this.name = "RequestTimeoutError";
	}
}

function isExpectedLiveWorkflowError(err: unknown) {
	if (err instanceof RequestTimeoutError) return true;
	return err instanceof ApiError && (err.status === 404 || err.status === 504);
}

function withRequestTimeout<T>(
	promise: Promise<T>,
	timeoutMs: number,
	label: string,
): Promise<T> {
	let timer: number | undefined;
	const timeout = new Promise<T>((_, reject) => {
		timer = window.setTimeout(() => {
			reject(new RequestTimeoutError(`${label} 请求超时`));
		}, timeoutMs);
	});
	return Promise.race([promise, timeout]).finally(() => {
		if (timer !== undefined) {
			window.clearTimeout(timer);
		}
	});
}

function normalizeInput(value?: string): string | undefined {
	return value?.trim() || undefined;
}

function isGeneratedChildTaskRouteName(value?: string): boolean {
	return /^task-[0-9A-Za-z]{6,}$/.test(value || "");
}

function buildWorkflowRunLookup(
	name?: string,
	runId?: string,
	runs: PipelineRunSummary[] = [],
): WorkflowRunLookup | null {
	return pickWorkflowLookupName(runs, name, runId);
}

async function resolveWorkflowLookupFromRunId(
	runId?: string,
	name?: string,
): Promise<WorkflowRunLookup | null> {
	const normalizedRunId = normalizeInput(runId);
	if (!normalizedRunId) return null;
	const normalizedRouteName = normalizeInput(name);
	try {
		const run = await getPipelineRun(normalizedRunId);
		const preferRunWorkflowName =
			normalizedRouteName && isGeneratedChildTaskRouteName(normalizedRouteName);
		const runWorkflowName =
			normalizeInput(run.workflowName) ?? normalizeInput(run.pipelineName);
		return {
			workflowName: preferRunWorkflowName
				? (runWorkflowName ?? normalizedRouteName ?? normalizedRunId)
				: (normalizedRouteName ?? runWorkflowName ?? normalizedRunId),
			runId: normalizedRunId,
			normalizedName: runWorkflowName ?? normalizedRouteName ?? normalizedRunId,
			runIdSource: "run-id",
		};
	} catch (err) {
		if (err instanceof ApiError && err.status === 404) {
			return {
				workflowName: normalizedRouteName ?? normalizedRunId,
				runId: normalizedRunId,
				normalizedName: normalizedRunId,
				runIdSource: "run-id",
			};
		}
		throw err;
	}
}

function getWorkflowLookupCandidates(
	lookup: WorkflowRunLookup | null,
	name?: string,
): string[] {
	if (!lookup) return [];
	const routeName = isGeneratedChildTaskRouteName(name)
		? undefined
		: normalizeInput(name);
	return uniqueLookupCandidates([
		routeName,
		lookup.workflowName,
		lookup.normalizedName,
		lookup.runId,
	]);
}

function findRunByLookup(
	runs: PipelineRunSummary[],
	lookup: WorkflowRunLookup | null,
): PipelineRunSummary | null {
	if (!lookup?.workflowName) return null;
	const exactById = lookup.runId
		? runs.find((run) => run.id === lookup.runId)
		: null;
	if (exactById) return exactById;

	const byWorkflowOrPipeline = runs.find(
		(run) =>
			run.workflowName === lookup.workflowName ||
			run.pipelineName === lookup.workflowName,
	);
	if (byWorkflowOrPipeline) return byWorkflowOrPipeline;

	const byWorkflowNameAsRunId = runs.find(
		(run) => run.id === lookup.workflowName,
	);
	if (byWorkflowNameAsRunId) return byWorkflowNameAsRunId;
	return null;
}

function toErrorMessage(err: unknown): string {
	if (err instanceof Error) {
		return err.message;
	}
	return String(err);
}

function toLoadError(err: unknown): WorkflowLoadError {
	if (err instanceof ApiError && err.status === 404) {
		return { kind: "not_found", message: err.message };
	}
	return { kind: "error", message: toErrorMessage(err) };
}

function appendBoundedLogContent(
	current: string | null,
	line: string,
): { content: string; truncated: boolean } {
	const prefix = current && !current.endsWith("\n") ? "\n" : "";
	const next = `${current ?? ""}${prefix}${line}\n`;
	if (next.length <= LOG_CLIENT_BUFFER_CHARS) {
		return { content: next, truncated: false };
	}
	return {
		content: next.slice(-LOG_CLIENT_BUFFER_CHARS),
		truncated: true,
	};
}

export function useWorkflowDetail(
	name?: string,
	runId?: string,
	options: UseWorkflowDetailOptions = {},
): UseWorkflowDetailResult {
	const skipAssetNodes = options.skipAssetNodes ?? false;
	const skipLiveWorkflow = options.skipLiveWorkflow ?? false;
	const [workflow, setWorkflow] = useState<WorkflowDetail | null>(null);
	const [loading, setLoading] = useState(true);
	const [loadError, setLoadError] = useState<WorkflowLoadError | null>(null);
	const [selectedNodeId, setSelectedNodeId] = useState<string | null>(null);
	const [logState, setLogState] = useState<WorkflowLogState>(EMPTY_LOG_STATE);
	const followSourceRef = useRef<EventSource | null>(null);
	const previousWorkflowStatusRef = useRef<string | null>(null);
	const [runEventState, setRunEventState] = useState<RunEventState>(
		EMPTY_RUN_EVENT_STATE,
	);
	const [runEventFilters, setRunEventFiltersState] = useState<RunEventFilters>(
		{},
	);
	const [assetNodeState, setAssetNodeState] = useState<AssetNodeState>(
		EMPTY_ASSET_NODE_STATE,
	);
	const [costSummaryState, setCostSummaryState] = useState<CostSummaryState>(
		EMPTY_COST_SUMMARY_STATE,
	);
	const [runDetailState, setRunDetailState] = useState<RunDetailState>(
		EMPTY_RUN_DETAIL_STATE,
	);
	const [workflowLookup, setWorkflowLookup] =
		useState<WorkflowRunLookup | null>(
			name ? { workflowName: name, runId: normalizeInput(runId) } : null,
		);
	const [lookupReady, setLookupReady] = useState(false);

	const resolveWorkflowLookup = useCallback(async () => {
		try {
			const resolvedFromRunId = await resolveWorkflowLookupFromRunId(
				runId,
				name,
			);
			if (resolvedFromRunId) {
				setWorkflowLookup(resolvedFromRunId);
				return resolvedFromRunId;
			}

			const runs = await listPipelineRuns({
				name: normalizeInput(runId) || normalizeInput(name),
			});
			const lookup = buildWorkflowRunLookup(name, runId, runs);
			setWorkflowLookup(lookup);
			return lookup;
		} catch (err) {
			console.error(err);
			const fallbackName = normalizeInput(name) ?? normalizeInput(runId);
			const fallback = fallbackName ? { workflowName: fallbackName } : null;
			setWorkflowLookup(fallback);
			return fallback;
		} finally {
			setLookupReady(true);
		}
	}, [name, runId]);

	useEffect(() => {
		setLookupReady(false);
		setWorkflowLookup((prev) => {
			const next = name
				? { workflowName: name, runId: normalizeInput(runId) }
				: null;
			const nextCacheKey = workflowLookupCacheKey(next);
			const prevCacheKey = workflowLookupCacheKey(prev);
			return next && nextCacheKey === prevCacheKey ? prev : next;
		});
		void resolveWorkflowLookup();
	}, [name, runId, resolveWorkflowLookup]);

	const fetchWorkflowByCandidates = useCallback(
		async (
			candidates: string[],
			context?: { runId?: string },
		): Promise<WorkflowDetail> => {
			let lastError: unknown;
			for (const candidate of candidates) {
				try {
					return await withRequestTimeout(
						getWorkflow(candidate, { runId: context?.runId }),
						WORKFLOW_DETAIL_REQUEST_TIMEOUT_MS,
						"加载工作流",
					);
				} catch (err) {
					lastError = err;
					if (err instanceof ApiError && err.status === 404) {
						continue;
					}
					throw err;
				}
			}
			if (lastError) throw lastError;
			throw new ApiError(404, "WORKFLOW_NOT_FOUND", "workflow not found");
		},
		[],
	);

	const loadWorkflow = useCallback(async () => {
		if (skipLiveWorkflow) {
			setWorkflow(null);
			setLoadError(null);
			setLoading(false);
			return;
		}
		if (!lookupReady || !workflowLookup?.workflowName) return;
		setLoading(true);
		setLoadError(null);
		try {
			const candidates = getWorkflowLookupCandidates(workflowLookup, name);
			const detail = await fetchWorkflowByCandidates(candidates, {
				runId: workflowLookup.runId,
			});
			setWorkflow(detail);
			setWorkflowLookup((current) =>
				current && detail.name && detail.name !== current.workflowName
					? {
							...current,
							workflowName: detail.name,
						}
					: current,
			);
			setLoadError(null);
		} catch (err) {
			if (!isExpectedLiveWorkflowError(err)) {
				console.error(err);
			}
			setWorkflow((current) => {
				if (current && !isExpectedLiveWorkflowError(err)) {
					return current;
				}
				return null;
			});
			setLoadError(toLoadError(err));
		} finally {
			setLoading(false);
		}
	}, [
		fetchWorkflowByCandidates,
		lookupReady,
		name,
		skipLiveWorkflow,
		workflowLookup,
	]);

	useEffect(() => {
		if (!lookupReady) return;
		loadWorkflow();
	}, [loadWorkflow, lookupReady]);

	const loadRunEvents = useCallback(
		(opts?: { append?: boolean; cursor?: number; quiet?: boolean }) => {
			if (!lookupReady || !workflowLookup?.workflowName) return;
			if (!opts?.quiet) {
				setRunEventState((current) => ({
					...current,
					loading: true,
					error: null,
				}));
				setRunDetailState((current) => ({
					...current,
					loading: true,
					error: null,
				}));
			}
			const resolveRunForEvents = async () => {
				try {
					if (!workflowLookup?.runId) {
						const runs = await withRequestTimeout(
							listPipelineRuns({
								name:
									normalizeInput(workflowLookup.workflowName) ||
									normalizeInput(name),
							}),
							RUN_LEDGER_REQUEST_TIMEOUT_MS,
							"加载运行历史",
						);
						return findRunByLookup(runs, workflowLookup);
					}
					const directRun = await withRequestTimeout(
						getPipelineRun(workflowLookup.runId),
						RUN_LEDGER_REQUEST_TIMEOUT_MS,
						"加载运行历史",
					);
					if (directRun) return directRun;
				} catch (err) {
					if (!(err instanceof ApiError && err.status === 404)) {
						throw err;
					}
					const runs = await withRequestTimeout(
						listPipelineRuns({
							name:
								normalizeInput(workflowLookup.workflowName) ||
								normalizeInput(workflowLookup.runId) ||
								normalizeInput(name),
						}),
						RUN_LEDGER_REQUEST_TIMEOUT_MS,
						"加载运行历史",
					);
					return findRunByLookup(runs, workflowLookup);
				}
				return null;
			};

			resolveRunForEvents()
				.then((run) => {
					if (!run) {
						setAssetNodeState({
							...EMPTY_ASSET_NODE_STATE,
							loading: false,
							error: null,
						});
						setRunDetailState({
							...EMPTY_RUN_DETAIL_STATE,
							loading: false,
							error: "未找到关联的 DataBrew pipeline run",
						});
						setRunEventState((current) => ({
							run: null,
							items: opts?.quiet ? current.items : [],
							nextCursor: opts?.quiet ? current.nextCursor : undefined,
							loading: false,
							error: "未找到关联的 DataBrew pipeline run",
						}));
						return;
					}
					setRunEventState((current) => ({
						...current,
						run,
						loading: !opts?.quiet,
						error: null,
					}));
					const cursor = opts?.append ? opts.cursor : undefined;
					const shouldLoadAssetNodes =
						!skipAssetNodes && (run.totalShards ?? 0) <= 0;
					return withRequestTimeout(
						Promise.all([
							optionalLedgerRequest(
								listPipelineRunEvents(run.id, {
									limit: 100,
									cursor,
									...runEventFilters,
								}),
							),
							shouldLoadAssetNodes
								? optionalLedgerRequest(
										listPipelineRunAssetNodes(run.id, { limit: 500 }),
									)
								: Promise.resolve({
										data: { items: [], summary: null, total: 0 },
										error: null,
									}),
							optionalLedgerRequest(getPipelineRunCostSummary(run.id)),
							optionalLedgerRequest(getPipelineRunNodeSummary(run.id)),
							optionalLedgerRequest(getPipelineRunFailureSummary(run.id)),
							optionalLedgerRequest(getPipelineRunBlocker(run.id)),
						]),
						RUN_LEDGER_REQUEST_TIMEOUT_MS,
						"加载运行历史",
					).then(
						([
							eventsResult,
							assetNodesResult,
							costSummaryResult,
							nodeSummaryResult,
							failureSummaryResult,
							blockerResult,
						]) => {
							const safeEvents = eventsResult.data ?? {
								items: [],
								nextCursor: undefined,
								total: 0,
							};
							const safeAssetNodes = assetNodesResult.data ?? {
								items: [],
								summary: null,
								total: 0,
							};
							const runDetailErrors = [
								nodeSummaryResult.error,
								failureSummaryResult.error,
								blockerResult.error,
							].filter(Boolean);

							setRunEventState((current) => ({
								run,
								items: opts?.append
									? [...current.items, ...(safeEvents.items ?? [])]
									: (safeEvents.items ?? []),
								nextCursor: safeEvents.nextCursor,
								loading: false,
								error: eventsResult.error,
							}));
							setAssetNodeState({
								items: safeAssetNodes.items ?? [],
								total:
									safeAssetNodes.total ?? safeAssetNodes.items?.length ?? 0,
								loading: false,
								error: assetNodesResult.error,
								summary: safeAssetNodes.summary ?? null,
							});
							setCostSummaryState({
								item: costSummaryResult.data ?? null,
								loading: false,
								error: costSummaryResult.error,
							});
							setRunDetailState({
								nodeSummary: nodeSummaryResult.data?.items ?? [],
								failureSummary: failureSummaryResult.data?.items ?? [],
								blocker: blockerResult.data?.type ? blockerResult.data : null,
								loading: false,
								error:
									runDetailErrors.length === 3
										? runDetailErrors.join("；")
										: null,
							});
						},
					);
				})
				.catch((err) => {
					console.error(err);
					setRunEventState((current) => ({
						...current,
						loading: false,
						error: toErrorMessage(err),
					}));
					setAssetNodeState((current) => ({
						...current,
						loading: false,
						error: toErrorMessage(err),
					}));
					setCostSummaryState((current) => ({
						...current,
						loading: false,
						error: toErrorMessage(err),
					}));
					setRunDetailState((current) => ({
						...current,
						loading: false,
						error: toErrorMessage(err),
					}));
				});
		},
		[workflowLookup, lookupReady, runEventFilters, name, skipAssetNodes],
	);

	useEffect(() => {
		loadRunEvents();
	}, [loadRunEvents]);

	const setRunEventFilters = useCallback((filters: RunEventFilters) => {
		setRunEventFiltersState(filters);
		setRunEventState((current) => ({ ...current, nextCursor: undefined }));
	}, []);

	useEffect(() => {
		if (!lookupReady || !workflowLookup?.workflowName || !workflow) {
			return;
		}
		if (skipLiveWorkflow) return;
		const normalizedStatus = normalizeWorkflowStatus(workflow.status);
		const isActive = ACTIVE_WORKFLOW_STATUSES.has(normalizedStatus);
		const isTerminal = TERMINAL_WORKFLOW_PHASES.has(normalizedStatus);
		if (!isActive && !isTerminal) {
			return;
		}
		const interval = isActive
			? WORKFLOW_POLL_INTERVAL_MS
			: TERMINAL_WORKFLOW_POLL_INTERVAL_MS;
		const candidates = getWorkflowLookupCandidates(workflowLookup, name);
		if (candidates.length === 0) return;

		const timer = window.setInterval(() => {
			void fetchWorkflowByCandidates(candidates, {
				runId: workflowLookup.runId,
			})
				.then((detail) => {
					setWorkflow(detail);
					setLoadError(null);
					loadRunEvents({ quiet: true });
				})
				.catch((err) => {
					if (!isExpectedLiveWorkflowError(err)) {
						console.error(err);
					}
				});
		}, interval);

		return () => window.clearInterval(timer);
	}, [
		fetchWorkflowByCandidates,
		loadRunEvents,
		lookupReady,
		skipLiveWorkflow,
		workflowLookup,
		name,
		workflow,
	]);

	useEffect(() => {
		const previousStatus = previousWorkflowStatusRef.current;
		const nextStatus = workflow?.status ?? null;
		previousWorkflowStatusRef.current = nextStatus;
		if (!nextStatus || !previousStatus) return;

		const wasActive = ACTIVE_WORKFLOW_STATUSES.has(
			previousStatus ? normalizeWorkflowStatus(previousStatus) : "",
		);
		const isNowTerminal = TERMINAL_WORKFLOW_PHASES.has(
			normalizeWorkflowStatus(nextStatus),
		);
		if (!wasActive || !isNowTerminal) return;

		loadRunEvents({ quiet: true });
		const timers = [
			window.setTimeout(() => loadRunEvents({ quiet: true }), 2_000),
			window.setTimeout(() => loadRunEvents({ quiet: true }), 8_000),
		];
		return () => {
			timers.forEach((timer) => {
				window.clearTimeout(timer);
			});
		};
	}, [loadRunEvents, workflow?.status]);

	const loadNodeLogs = useCallback(
		async (nodeId: string) => {
			const workflowName = workflow?.name || workflowLookup?.workflowName;
			if (!workflowName) return;
			setLogState((current) => ({
				...current,
				loading: true,
				error: null,
			}));
			try {
				const res = await getWorkflowLogs(
					workflowName,
					nodeId,
					{},
					{
						runId: workflowLookup?.runId,
					},
				);
				setLogState((current) => ({
					content: res.logs || "",
					loading: false,
					error: null,
					search: current.search,
					following: current.following,
					followStatus: current.followStatus,
					followMessage: current.followMessage,
					response: res,
					clientTruncated: false,
				}));
			} catch (err) {
				setLogState((current) => ({
					content: null,
					loading: false,
					error: toErrorMessage(err),
					search: current.search,
					following: current.following,
					followStatus: current.followStatus,
					followMessage: current.followMessage,
					response: null,
					clientTruncated: false,
				}));
			}
		},
		[workflow?.name, workflowLookup?.workflowName, workflowLookup?.runId],
	);

	const selectNode = useCallback(
		(node: WorkflowNodeStatus | null) => {
			if (!node || !workflowLookup?.workflowName) {
				setSelectedNodeId(null);
				setLogState((current) => ({
					...EMPTY_LOG_STATE,
					search: current.search,
				}));
				return;
			}
			setSelectedNodeId(node.id);
			if (node.id !== selectedNodeId) {
				setLogState((current) => ({
					...current,
					content: "",
					loading: false,
					error: null,
					response: null,
					clientTruncated: false,
				}));
			}
		},
		[workflowLookup?.workflowName, selectedNodeId],
	);

	const displayWorkflow = useMemo(
		() =>
			applyPipelineNodeDisplayNames(workflow, runEventState.run?.pipelineJSON),
		[runEventState.run?.pipelineJSON, workflow],
	);

	const selectedNode = useMemo(() => {
		if (!displayWorkflow || !selectedNodeId) return null;
		return (
			displayWorkflow.nodes.find((node) => node.id === selectedNodeId) ?? null
		);
	}, [displayWorkflow, selectedNodeId]);

	const stopFollowLogs = useCallback(() => {
		if (followSourceRef.current) {
			followSourceRef.current.close();
			followSourceRef.current = null;
		}
		setLogState((prev) => ({
			...prev,
			following: false,
			followStatus: "idle",
			followMessage: "实时日志已停止",
		}));
	}, []);

	const startFollowLogs = useCallback(() => {
		const workflowName = workflow?.name || workflowLookup?.workflowName;
		if (!workflowName || !selectedNodeId) return;

		stopFollowLogs();

		const url = getWorkflowLogStreamUrl(
			workflowName,
			selectedNodeId,
			{},
			{
				runId: workflowLookup?.runId,
			},
		);
		const source = new EventSource(url);
		followSourceRef.current = source;

		setLogState((prev) => ({
			...prev,
			following: true,
			followStatus: "connecting",
			followMessage: "正在连接实时日志",
			error: null,
		}));

		source.onopen = () => {
			setLogState((prev) => ({
				...prev,
				following: true,
				followStatus: "connected",
				followMessage: "实时日志已连接",
			}));
		};

		source.addEventListener("log", (event: MessageEvent) => {
			try {
				const data = JSON.parse(event.data);
				const line =
					typeof data.line === "string"
						? data.line
						: typeof data.content === "string"
							? data.content
							: "";
				if (line) {
					setLogState((prev) => ({
						...prev,
						...(() => {
							const next = appendBoundedLogContent(prev.content, line);
							return {
								content: next.content,
								clientTruncated: prev.clientTruncated || next.truncated,
							};
						})(),
						loading: false,
						followStatus: "connected",
						followMessage: "实时日志已连接",
					}));
				}
			} catch {
				// ignore malformed events
			}
		});

		source.addEventListener("end", (event: MessageEvent) => {
			let reason = "实时日志已结束";
			try {
				const data = JSON.parse(event.data);
				if (typeof data.reason === "string" && data.reason) {
					reason =
						data.reason === "limit-bytes"
							? "已达到本次实时日志字节上限"
							: "实时日志已结束";
				}
			} catch {
				// ignore malformed events
			}
			source.close();
			if (followSourceRef.current === source) {
				followSourceRef.current = null;
			}
			setLogState((prev) => ({
				...prev,
				following: false,
				followStatus:
					selectedNode && ACTIVE_NODE_PHASES.has(selectedNode.phase)
						? "polling"
						: "ended",
				followMessage: reason,
			}));
		});

		source.onerror = () => {
			source.close();
			if (followSourceRef.current === source) {
				followSourceRef.current = null;
			}
			setLogState((prev) => ({
				...prev,
				following: false,
				followStatus:
					selectedNode && ACTIVE_NODE_PHASES.has(selectedNode.phase)
						? "polling"
						: "error",
				followMessage:
					selectedNode && ACTIVE_NODE_PHASES.has(selectedNode.phase)
						? "实时日志连接已断开，已切换为轮询刷新"
						: "实时日志连接已断开",
			}));
		};
	}, [
		workflow?.name,
		workflowLookup?.workflowName,
		workflowLookup?.runId,
		selectedNode,
		selectedNodeId,
		stopFollowLogs,
	]);

	const downloadLogs = useCallback(() => {
		const content = logState.content;
		const selNode = selectedNode;
		const workflowName = workflow?.name || workflowLookup?.workflowName;
		if (!content || !workflowName || !selNode) return;
		const nodeName = selNode.displayName || selNode.name || selNode.id;
		const response = logState.response;
		const header = [
			`# workflow: ${workflowName}`,
			`# node: ${nodeName}`,
			`# container: ${response?.container ?? "main"}`,
			`# scope: ${response?.window?.scope ?? "loaded-log-window"}`,
			`# tailLines: ${response?.truncation?.tailLines ?? "unknown"}`,
			`# limitBytes: ${response?.truncation?.limitBytes ?? "unknown"}`,
			`# generatedAt: ${new Date().toISOString()}`,
			"",
		].join("\n");
		const blob = new Blob([header, content], { type: "text/plain" });
		const url = URL.createObjectURL(blob);
		const a = document.createElement("a");
		a.href = url;
		a.download = `${workflowName}-${nodeName}.log`;
		a.click();
		URL.revokeObjectURL(url);
	}, [
		logState.content,
		logState.response,
		selectedNode,
		workflow?.name,
		workflowLookup?.workflowName,
	]);

	useEffect(() => {
		return () => {
			if (followSourceRef.current) {
				followSourceRef.current.close();
				followSourceRef.current = null;
			}
		};
	}, []);

	useEffect(() => {
		if (!selectedNodeId || !name) {
			return;
		}
		void loadNodeLogs(selectedNodeId);
	}, [loadNodeLogs, name, selectedNodeId]);

	useEffect(() => {
		if (!selectedNodeId || !selectedNode) return;
		if (!ACTIVE_NODE_PHASES.has(selectedNode.phase)) return;
		if (logState.following && logState.followStatus === "connected") return;

		const timer = window.setInterval(() => {
			void loadNodeLogs(selectedNodeId);
			setLogState((current) => ({
				...current,
				followStatus:
					current.following && current.followStatus === "connected"
						? current.followStatus
						: "polling",
				followMessage:
					current.following && current.followStatus === "connected"
						? current.followMessage
						: "实时日志连接不可用，正在轮询刷新当前日志窗口",
			}));
		}, LOG_POLL_INTERVAL_MS);
		return () => window.clearInterval(timer);
	}, [
		loadNodeLogs,
		logState.following,
		logState.followStatus,
		selectedNode,
		selectedNodeId,
	]);

	useEffect(() => {
		if (!workflow || !selectedNodeId) return;
		const selectedNodeExists = workflow.nodes.some(
			(node) => node.id === selectedNodeId,
		);
		if (!selectedNodeExists) {
			setSelectedNodeId(null);
			setLogState((current) => ({
				...EMPTY_LOG_STATE,
				search: current.search,
			}));
		}
	}, [selectedNodeId, workflow]);
	const statusSyncWarning = useMemo(() => {
		return workflow
			? buildStatusSyncWarning(workflow, runEventState.run?.status)
			: undefined;
	}, [runEventState.run?.status, workflow]);

	return {
		workflow: displayWorkflow,
		loading,
		loadError,
		statusSyncWarning,
		selectedNode,
		loadWorkflow,
		selectNode,
		startFollowLogs,
		stopFollowLogs,
		downloadLogs,
		logState: {
			...logState,
		},
		runEventState: {
			...runEventState,
			items: [...runEventState.items],
		},
		runEventFilters: { ...runEventFilters },
		setRunEventFilters,
		loadRunEvents,
		assetNodeState: {
			...assetNodeState,
			items: [...assetNodeState.items],
		},
		costSummaryState: { ...costSummaryState },
		runDetailState: {
			...runDetailState,
			nodeSummary: [...runDetailState.nodeSummary],
			failureSummary: [...runDetailState.failureSummary],
		},
		setLogSearch: useCallback((query: string) => {
			setLogState((current) => ({ ...current, search: query }));
		}, []),
	};
}
