import {
	CloudServerOutlined,
	CodeOutlined,
	FileTextOutlined,
	InfoCircleOutlined,
	LineChartOutlined,
	QuestionCircleOutlined,
	ReloadOutlined,
	WarningOutlined,
} from "@ant-design/icons";
import { Handle, type Node, type NodeProps, Position } from "@xyflow/react";
import { Button, Tag, Tooltip } from "antd";
import dayjs from "dayjs";
import type { MouseEvent, PointerEvent } from "react";
import type { PipelineNodeSummary } from "../api/pipelineApi";
import type { WorkflowNodeStatus } from "../api/workflowApi";
import {
	PHASE_COLORS,
	STATUS_ICONS,
	WORKFLOW_PHASE_LABELS,
} from "../lib/constants";
import { getWorkflowNodeDisplayText } from "../lib/workflowNodeDisplay";
import "./WorkflowDagNode.css";

const PROGRESS_RING_SIZE = 18;
const PROGRESS_RING_STROKE = 2.5;
const WAITING_NODE_PHASES = new Set(["Pending", "Waiting", "Queued"]);
const READONLY_HANDLE_STYLE: React.CSSProperties = {
	opacity: 0,
	pointerEvents: "none",
};

export type WorkflowDagNodeAction =
	| "summary"
	| "logs"
	| "runtime"
	| "monitoring"
	| "terminal"
	| "retry";

export interface WorkflowDagNodeData extends Record<string, unknown> {
	workflowNode: WorkflowNodeStatus;
	selected: boolean;
	dimmed: boolean;
	progressPercent: number | null;
	nodeSummary?: PipelineNodeSummary;
	onAction?: (node: WorkflowNodeStatus, action: WorkflowDagNodeAction) => void;
}

function getProgressRingColor(phase: string): string {
	if (phase === "Succeeded") return PHASE_COLORS.Succeeded;
	if (phase === "Running") return PHASE_COLORS.Running;
	return "#94a3b8";
}

function getNodeRelativeTime(node: WorkflowNodeStatus): string | null {
	const startedAt = node.startedAt;
	if (!startedAt) return null;
	const started = dayjs(startedAt);
	if (!started.isValid()) return null;
	if (node.finishedAt) {
		const finished = dayjs(node.finishedAt);
		if (finished.isValid()) {
			return finished.fromNow();
		}
	}
	return started.fromNow();
}

function getMessageSummary(message?: string): string | null {
	const normalized = message?.replace(/\s+/g, " ").trim();
	if (!normalized) return null;
	return normalized.length > 92 ? `${normalized.slice(0, 89)}...` : normalized;
}

function inferRunningSubstatus(phase: string, message?: string): string | null {
	if (phase === "Running") return "执行中";
	if (!WAITING_NODE_PHASES.has(phase)) return null;
	const normalized = (message || "").toLowerCase();
	if (
		normalized.includes("dependency") ||
		normalized.includes("依赖") ||
		normalized.includes("upstream") ||
		normalized.includes("downstream")
	) {
		return "等待依赖";
	}
	return "等待资源";
}

function runningStateText(phase: string, message?: string): string | null {
	if (phase === "Running" || WAITING_NODE_PHASES.has(phase)) {
		return inferRunningSubstatus(phase, message);
	}
	return null;
}

function canOpenLogs(node: WorkflowNodeStatus): boolean {
	if (node.debug?.logStreamEnabled === false && !node.podName) return false;
	return Boolean(node.id);
}

function canOpenRuntime(node: WorkflowNodeStatus): boolean {
	if (
		node.debug?.logStreamEnabled === false &&
		node.debug?.metricsEnabled === false &&
		!node.podName
	) {
		return false;
	}
	return Boolean(node.id);
}

function canOpenMonitoring(node: WorkflowNodeStatus): boolean {
	if (node.debug?.metricsEnabled === false && !node.podName) return false;
	return Boolean(node.id);
}

function ProgressRing({ percent, color }: { percent: number; color: string }) {
	const size = PROGRESS_RING_SIZE;
	const center = size / 2;
	const radius = center - PROGRESS_RING_STROKE / 2;
	const circumference = 2 * Math.PI * radius;
	const dashOffset = circumference - (percent / 100) * circumference;

	return (
		<svg
			className="workflow-dag-node__progress-ring"
			width={size}
			height={size}
			viewBox={`0 0 ${size} ${size}`}
			aria-hidden="true"
		>
			<circle
				cx={center}
				cy={center}
				r={radius}
				fill="none"
				stroke="#e2e8f0"
				strokeWidth={PROGRESS_RING_STROKE}
			/>
			<circle
				cx={center}
				cy={center}
				r={radius}
				fill="none"
				stroke={color}
				strokeWidth={PROGRESS_RING_STROKE}
				strokeDasharray={`${circumference} ${circumference}`}
				strokeDashoffset={dashOffset}
				transform={`rotate(-90 ${center} ${center})`}
				strokeLinecap="round"
			/>
		</svg>
	);
}

export function WorkflowDagNode({
	data,
}: NodeProps<Node<WorkflowDagNodeData>>): React.JSX.Element {
	const { workflowNode, selected, dimmed, progressPercent, nodeSummary } = data;
	const displayText = getWorkflowNodeDisplayText(workflowNode);
	const technicalText =
		workflowNode.technicalDisplayName ||
		workflowNode.templateName ||
		workflowNode.name ||
		workflowNode.id;
	const titleText =
		technicalText && technicalText !== displayText
			? `${displayText}\n技术ID: ${technicalText}`
			: displayText;
	const phase = workflowNode.phase;
	const accent = PHASE_COLORS[phase] || "#64748b";
	const phaseLabel =
		WORKFLOW_PHASE_LABELS[phase as keyof typeof WORKFLOW_PHASE_LABELS] || phase;
	const relTime = getNodeRelativeTime(workflowNode);
	const isRunning = phase === "Running";
	const isFailed = phase === "Failed" || phase === "Error";
	const messageSummary = isFailed
		? getMessageSummary(workflowNode.message)
		: null;
	const waitingReasonSummary = !isFailed
		? getMessageSummary(workflowNode.message)
		: null;
	const subStatus = runningStateText(phase, workflowNode.message);
	const terminalEnabled = workflowNode.debug?.execEnabled === true;
	const terminalTooltip = terminalEnabled
		? "终端"
		: workflowNode.debug?.reason || "终端仅支持运行中的 Pod";
	const logsEnabled = canOpenLogs(workflowNode);
	const runtimeEnabled = canOpenRuntime(workflowNode);
	const monitoringEnabled = canOpenMonitoring(workflowNode);
	const runtimeUnavailableReason =
		workflowNode.debug?.reason || "当前节点没有绑定实时 Pod";
	const aggregateLine =
		nodeSummary && nodeSummary.total > 0
			? {
					total: nodeSummary.total.toLocaleString(),
					success: nodeSummary.succeeded.toLocaleString(),
					failed: nodeSummary.failed.toLocaleString(),
					running: nodeSummary.running.toLocaleString(),
					queued: nodeSummary.queued.toLocaleString(),
					cached: nodeSummary.cached.toLocaleString(),
					qualityFailed: nodeSummary.qualityFailed.toLocaleString(),
					tainted: nodeSummary.tainted.toLocaleString(),
					failedCount: nodeSummary.failed,
					cachedCount: nodeSummary.cached,
					qualityFailedCount: nodeSummary.qualityFailed,
					taintedCount: nodeSummary.tainted,
				}
			: null;

	const stopNodeActionEvent = (
		event: MouseEvent<HTMLElement> | PointerEvent<HTMLElement>,
	) => {
		event.preventDefault();
		event.stopPropagation();
	};
	const openAction =
		(action: WorkflowDagNodeAction) => (event: MouseEvent<HTMLElement>) => {
			stopNodeActionEvent(event);
			data.onAction?.(workflowNode, action);
		};

	return (
		<div
			className={[
				"workflow-dag-node",
				selected ? "workflow-dag-node--selected" : "",
				dimmed ? "workflow-dag-node--dimmed" : "",
				isRunning ? "workflow-dag-node--running" : "",
				isFailed ? "workflow-dag-node--failed" : "",
			]
				.filter(Boolean)
				.join(" ")}
			style={{ "--workflow-dag-accent": accent } as React.CSSProperties}
		>
			<Handle
				type="target"
				position={Position.Left}
				className="workflow-dag-node__handle workflow-dag-node__handle--target"
				style={READONLY_HANDLE_STYLE}
			/>
			<Handle
				type="source"
				position={Position.Right}
				className="workflow-dag-node__handle workflow-dag-node__handle--source"
				style={READONLY_HANDLE_STYLE}
			/>

			<div className="workflow-dag-node__accent" aria-hidden="true" />

			<div className="workflow-dag-node__body">
				<div className="workflow-dag-node__header">
					<div className="workflow-dag-node__title" title={titleText}>
						{displayText}
					</div>
					{progressPercent !== null ? (
						<ProgressRing
							percent={progressPercent}
							color={getProgressRingColor(phase)}
						/>
					) : null}
				</div>

				<div className="workflow-dag-node__meta">
					<Tag
						className="workflow-dag-node__phase-tag"
						icon={STATUS_ICONS[phase]}
						color={phase === "Pending" ? "default" : undefined}
						style={
							phase !== "Pending"
								? {
										color: accent,
										background: `${accent}14`,
										borderColor: `${accent}33`,
									}
								: undefined
						}
					>
						{phaseLabel}
					</Tag>
					{relTime ? (
						<Tooltip
							title={
								workflowNode.startedAt
									? dayjs(workflowNode.startedAt).format("YYYY-MM-DD HH:mm:ss")
									: ""
							}
						>
							<span className="workflow-dag-node__time">{relTime}</span>
						</Tooltip>
					) : null}
				</div>

				{aggregateLine ? (
					<div className="workflow-dag-node__aggregate">
						<div>
							总数 {aggregateLine.total} · 成功 {aggregateLine.success}
							{aggregateLine.failedCount > 0 ? (
								<span className="workflow-dag-node__aggregate-failed">
									{" "}
									· 失败 {aggregateLine.failed}
								</span>
							) : null}
						</div>
						<div>
							运行 {aggregateLine.running} · 排队 {aggregateLine.queued}
							{aggregateLine.cachedCount > 0
								? ` · 缓存 ${aggregateLine.cached}`
								: ""}
						</div>
						{aggregateLine.qualityFailedCount > 0 ||
						aggregateLine.taintedCount > 0 ? (
							<div>
								{aggregateLine.qualityFailedCount > 0 ? (
									<span className="workflow-dag-node__aggregate-warning">
										质量失败 {aggregateLine.qualityFailed}
									</span>
								) : null}
								{aggregateLine.qualityFailedCount > 0 &&
								aggregateLine.taintedCount > 0
									? " · "
									: ""}
								{aggregateLine.taintedCount > 0 ? (
									<span className="workflow-dag-node__aggregate-failed">
										污染 {aggregateLine.tainted}
									</span>
								) : null}
							</div>
						) : null}
					</div>
				) : null}

				{messageSummary ? (
					<Tooltip title={workflowNode.message}>
						<div className="workflow-dag-node__message">
							<WarningOutlined />
							<span>{messageSummary}</span>
						</div>
					</Tooltip>
				) : null}
				{!isFailed && subStatus ? (
					<Tooltip title={workflowNode.message || subStatus}>
						<div className="workflow-dag-node__status">
							<QuestionCircleOutlined />
							<span>{subStatus}</span>
						</div>
					</Tooltip>
				) : null}
				{!isFailed && !subStatus && waitingReasonSummary ? (
					<Tooltip title={workflowNode.message}>
						<div className="workflow-dag-node__message">
							<WarningOutlined />
							<span>{waitingReasonSummary}</span>
						</div>
					</Tooltip>
				) : null}
				{isFailed && logsEnabled ? (
					<div
						className="workflow-dag-node__failed-actions"
						style={{ marginTop: 4 }}
					>
						<Button
							size="small"
							icon={<ReloadOutlined />}
							onClick={openAction("retry")}
						>
							重试节点
						</Button>
						<Button
							size="small"
							danger
							icon={<FileTextOutlined />}
							onClick={openAction("logs")}
						>
							查看失败日志
						</Button>
					</div>
				) : null}

				<fieldset
					className="workflow-dag-node__actions nodrag nopan"
					aria-label="节点操作"
					onPointerDown={stopNodeActionEvent}
					onMouseDown={stopNodeActionEvent}
				>
					<Tooltip title={logsEnabled ? "查看日志" : runtimeUnavailableReason}>
						<Button
							className="nodrag nopan"
							type="text"
							size="small"
							shape="circle"
							icon={<FileTextOutlined />}
							aria-label="查看日志"
							disabled={!logsEnabled}
							onClick={logsEnabled ? openAction("logs") : undefined}
							onPointerDown={stopNodeActionEvent}
							onMouseDown={stopNodeActionEvent}
						/>
					</Tooltip>
					<Tooltip
						title={runtimeEnabled ? "运行环境" : runtimeUnavailableReason}
					>
						<Button
							className="nodrag nopan"
							type="text"
							size="small"
							shape="circle"
							icon={<CloudServerOutlined />}
							aria-label="运行环境"
							disabled={!runtimeEnabled}
							onClick={runtimeEnabled ? openAction("runtime") : undefined}
							onPointerDown={stopNodeActionEvent}
							onMouseDown={stopNodeActionEvent}
						/>
					</Tooltip>
					<Tooltip
						title={monitoringEnabled ? "监控总览" : runtimeUnavailableReason}
					>
						<Button
							className="nodrag nopan"
							type="text"
							size="small"
							shape="circle"
							icon={<LineChartOutlined />}
							aria-label="监控总览"
							disabled={!monitoringEnabled}
							onClick={monitoringEnabled ? openAction("monitoring") : undefined}
							onPointerDown={stopNodeActionEvent}
							onMouseDown={stopNodeActionEvent}
						/>
					</Tooltip>
					<Tooltip title={terminalTooltip}>
						<Button
							className="nodrag nopan"
							type="text"
							size="small"
							shape="circle"
							icon={<CodeOutlined />}
							aria-label="终端"
							disabled={!terminalEnabled}
							onClick={terminalEnabled ? openAction("terminal") : undefined}
							onPointerDown={stopNodeActionEvent}
							onMouseDown={stopNodeActionEvent}
						/>
					</Tooltip>
					<Tooltip title="详情">
						<Button
							className="nodrag nopan"
							type="text"
							size="small"
							shape="circle"
							icon={<InfoCircleOutlined />}
							aria-label="详情"
							onClick={openAction("summary")}
							onPointerDown={stopNodeActionEvent}
							onMouseDown={stopNodeActionEvent}
						/>
					</Tooltip>
				</fieldset>
			</div>
		</div>
	);
}
