type GroupedRunEvent = {
	event: PipelineRunEvent;
	durationMs?: number;
};

type RunEventGroup = {
	stage: RunEventTimelineStage;
	events: GroupedRunEvent[];
	totalMs: number;
};

function formatEventTime(value: string) {
	const date = new Date(value);
	if (Number.isNaN(date.getTime())) {
		return value || "-";
	}
	return date.toLocaleString();
}

function eventTagColor(event: PipelineRunEvent) {
	const status = event.status || event.eventType;
	if (/failed|error/i.test(status)) return "red";
	if (/succeeded|completed/i.test(status)) return "green";
	if (/running|started|submitted|created/i.test(status)) return "blue";
	if (/stop|delete|retry|resubmit/i.test(status)) return "orange";
	return "default";
}

function formatRunEventError(error: string) {
	if (error.includes("未找到关联的 DataBrew pipeline run")) {
		return "暂无 DataBrew 运行事件。该工作流可能由 Argo 外部提交，仍可查看 DAG、Pod 和日志。";
	}
	return error;
}

function shortEventSubject(event: PipelineRunEvent) {
	if (event.subjectType === "run") return "运行";
	if (event.subjectType === "workflow") return "Workflow";
	if (event.subjectType === "node") return "节点";
	if (event.subjectType === "pod") return "Pod";
	return event.subjectType || "对象";
}

function normalizeEventStatus(event: PipelineRunEvent) {
	const source = `${event.status ?? event.eventType ?? ""} ${event.message ?? ""}`;
	return source.toLowerCase();
}

function getRunEventTime(event: PipelineRunEvent) {
	const raw = new Date(event.occurredAt).getTime();
	return Number.isFinite(raw) ? raw : undefined;
}

function formatEventDurationSeconds(totalMs?: number) {
	if (!Number.isFinite(totalMs ?? NaN) || totalMs === undefined) return "—";
	const rounded = Math.max(0, Math.round(totalMs / 1000));
	if (rounded === 0) return "0s";
	const seconds = rounded;
	const minutes = Math.floor(seconds / 60);
	if (minutes > 0) {
		return `${minutes}m ${seconds % 60}s`;
	}
	return `${seconds}s`;
}

function getRunEventStage(event: PipelineRunEvent): RunEventTimelineStage {
	const normalized = (event.eventType || "").toLowerCase();
	if (RUN_EVENT_STAGE_KEYWORDS.prepare.has(normalized)) {
		return "prepare";
	}
	if (RUN_EVENT_STAGE_KEYWORDS.execution.has(normalized)) {
		return "execution";
	}
	if (RUN_EVENT_STAGE_KEYWORDS.finalize.has(normalized)) {
		return "finalize";
	}
	return "other";
}

function buildRunEventGroups(events: PipelineRunEvent[]): RunEventGroup[] {
	const dedupedEvents = dedupeConsecutiveEvents(events)
		.map((event) => ({
			event,
			time: getRunEventTime(event),
			stage: getRunEventStage(event),
		}))
		.sort((lhs, rhs) => {
			if (lhs.time === undefined && rhs.time === undefined) return 0;
			if (lhs.time === undefined) return 1;
			if (rhs.time === undefined) return -1;
			return lhs.time - rhs.time;
		});

	return dedupedEvents.reduce<RunEventGroup[]>((groups, current, index) => {
		const next = dedupedEvents[index + 1];
		const durationMs =
			current.time !== undefined && next?.time !== undefined
				? next.time - current.time
				: undefined;
		const row = {
			event: current.event,
			durationMs,
		};
		const last = groups[groups.length - 1];
		if (!last || last.stage !== current.stage) {
			groups.push({
				stage: current.stage,
				events: [row],
				totalMs: durationMs || 0,
			});
			return groups;
		}
		last.events.push(row);
		if (durationMs && durationMs > 0) {
			last.totalMs += durationMs;
		}
		return groups;
	}, []);
}

function countEventErrors(events: PipelineRunEvent[]) {
	return events.reduce((acc, event) => {
		const source = normalizeEventStatus(event);
		return /failed|error/.test(source) ? acc + 1 : acc;
	}, 0);
}

function countEventWarnings(events: PipelineRunEvent[]) {
	return events.reduce((acc, event) => {
		const source = normalizeEventStatus(event);
		return /warn|retry|resubmit|stop|suspend|delete|terminate|cancel/.test(
			source,
		)
			? acc + 1
			: acc;
	}, 0);
}

function getNodeRuntimeCounts(nodes: WorkflowNodeStatus[]) {
	const runtimeNodes = nodes.filter((node) => {
		const type = (node.type || "").toLowerCase();
		return type !== "dag" && type !== "steps";
	});
	const total = runtimeNodes.length;
	const succeeded = runtimeNodes.filter(
		(node) => node.phase.toLowerCase() === "succeeded",
	).length;
	const failed = runtimeNodes.filter(
		(node) =>
			node.phase.toLowerCase() === "failed" ||
			node.phase.toLowerCase() === "error",
	).length;
	const running = runtimeNodes.filter(
		(node) =>
			node.phase.toLowerCase() === "running" ||
			node.phase.toLowerCase() === "pending" ||
			node.phase.toLowerCase() === "waiting" ||
			node.phase.toLowerCase() === "queued",
	).length;
	const retried = runtimeNodes.filter((node) =>
		/重试|retry/i.test(node.message || ""),
	).length;
	return { total, succeeded, failed, running, retried };
}

const WAITING_NODE_SUBSTATUS: Array<string> = [
	"Pending",
	"Running",
	"Waiting",
	"Queued",
	"Initializing",
	"ContainerCreating",
	"PodInitializing",
	"Suspended",
];
const WAITING_NODE_PHASES = new Set(
	WAITING_NODE_SUBSTATUS.map((value) => value.toLowerCase()),
);

function getWorkflowNodeSubstatus(phase: string, message?: string) {
	const normalized = phase.toLowerCase();
	if (normalized === "running") return "执行中";
	if (WAITING_NODE_PHASES.has(normalized)) {
		const lowerMessage = (message || "").toLowerCase();
		if (
			lowerMessage.includes("dependency") ||
			lowerMessage.includes("依赖") ||
			lowerMessage.includes("upstream") ||
			lowerMessage.includes("downstream")
		) {
			return "等待依赖";
		}
		if (
			lowerMessage.includes("cpu") ||
			lowerMessage.includes("memory") ||
			lowerMessage.includes("resource") ||
			lowerMessage.includes("ready") ||
			lowerMessage.includes("pod")
		) {
			return "等待资源";
		}
		return "等待资源";
	}
	return normalized === "suspended" ? "已暂停" : undefined;
}

function getWorkflowCurrentBottleneck(nodes: WorkflowNodeStatus[]) {
	const runtimeNodes = nodes.filter((node) => {
		const type = (node.type || "").toLowerCase();
		return type !== "dag" && type !== "steps";
	});
	const activeNode = runtimeNodes.find((node) =>
		WAITING_NODE_PHASES.has((node.phase || "").toLowerCase()),
	);
	if (!activeNode) {
		return null;
	}
	const displayName =
		activeNode.displayName ||
		activeNode.templateName ||
		activeNode.name ||
		activeNode.id;
	return {
		node: activeNode,
		displayName,
		subStatus: getWorkflowNodeSubstatus(activeNode.phase, activeNode.message),
	};
}

function formatBusinessOutputSummary(node?: WorkflowNodeStatus) {
	if (!node?.outputs) return [];
	const outputEntries: string[] = [];
	if ((node.outputs?.parameters?.length ?? 0) > 0) {
		outputEntries.push(
			...(node.outputs?.parameters ?? [])
				.filter((item) => item.name)
				.map((item) => `${item.name}=${item.value ?? "—"}`),
		);
	}
	if ((node.outputs?.artifacts?.length ?? 0) > 0) {
		outputEntries.push(
			...(node.outputs?.artifacts ?? [])
				.filter((item) => item.name)
				.map((item) => `artifact:${item.name}`),
		);
	}
	const result = node.outputs?.result?.trim();
	if (result) {
		outputEntries.push(`result=${result}`);
	}
	return outputEntries;
}

function getRunAssetIds(workflow: WorkflowDetail, runEventAssets?: string[]) {
	if (runEventAssets && runEventAssets.length > 0) return runEventAssets;
	const labels = workflow.labels;
	const labelValue =
		getWorkflowLabel(labels, "asset-ids") ||
		getWorkflowLabel(labels, "asset_ids");
	if (!labelValue) return [];
	return labelValue
		.split(",")
		.map((item) => item.trim())
		.filter(Boolean);
}

function sumNodeSummaries(items: PipelineNodeSummary[]) {
	return items.reduce(
		(acc, item) => {
			acc.total += item.total || 0;
			acc.succeeded += item.succeeded || 0;
			acc.failed += item.failed || 0;
			acc.running += item.running || 0;
			acc.queued += item.queued || 0;
			acc.cached += item.cached || 0;
			acc.qualityFailed += item.qualityFailed || 0;
			acc.tainted += item.tainted || 0;
			return acc;
		},
		{
			total: 0,
			succeeded: 0,
			failed: 0,
			running: 0,
			queued: 0,
			cached: 0,
			qualityFailed: 0,
			tainted: 0,
		},
	);
}

function formatNumber(value?: number | null) {
	return typeof value === "number" && Number.isFinite(value)
		? value.toLocaleString()
		: "0";
}

function formatOptionalNumber(value?: number | null) {
	return typeof value === "number" && Number.isFinite(value)
		? value.toLocaleString()
		: "后端未返回";
}

function getStatusColor(status?: string) {
	const raw = status || "";
	const normalized = raw.charAt(0).toUpperCase() + raw.slice(1).toLowerCase();
	return STATUS_COLORS[raw] || STATUS_COLORS[normalized] || "default";
}

function formatRunType(run?: {
	triggerSource?: string;
	totalShards?: number;
	parentRunId?: string;
	repairReason?: string;
}) {
	const source = (run?.triggerSource || "").toLowerCase();
	if ((run?.totalShards ?? 0) > 0) return "Batch Run";
	if (run?.repairReason || source === "repair") return "Repair Run";
	if (run?.parentRunId || source === "retry") return "Retry Run";
	if (source === "backfill") return "Backfill Run";
	if (source === "batch") return "Batch Run";
	if (source === "asset_run") return "Asset Run";
	if (source === "api") return "API Run";
	return "Normal Run";
}

function isInternalShardWorkflowName(name?: string) {
	return /(?:^|-)shard-\d{3}(?:-|$)/i.test(name || "");
}

function formatPipelineNameForDisplay(run?: {
	pipelineName?: string;
	templateName?: string;
	workflowName?: string;
}) {
	const rawName =
		run?.pipelineName || run?.templateName || run?.workflowName || "";
	if (!rawName) return "后端未返回";
	return rawName.replace(/-shard-\d{3}(?:-.+)?$/i, "");
}

function formatLedgerDetailTitle(
	name?: string,
	routeRunId?: string,
	parentRunId?: string,
) {
	if (parentRunId || isInternalShardWorkflowName(name)) {
		return routeRunId ? `任务 ${formatRunIdShort(routeRunId)}` : "任务详情";
	}
	return name || "运行详情";
}

function blockerAlertType(
	severity?: PipelineRunBlocker["severity"],
): "info" | "warning" | "error" {
	if (severity === "error") return "error";
	if (severity === "warning") return "warning";
	return "info";
}

function CurrentRunBlockerCard({
	blocker,
	loading,
	error,
	onJumpToNode,
}: {
	blocker: PipelineRunBlocker | null;
	loading: boolean;
	error: string | null;
	onJumpToNode: (nodeKey?: string) => void;
}) {
	if (loading && !blocker) return null;
	if (error && !blocker) {
		return (
			<div style={{ padding: "8px 24px 0", background: "#f8fafc" }}>
				<Alert
					type="warning"
					showIcon
					message="运行诊断暂不可用"
					description={error}
					style={{ borderRadius: 6 }}
				/>
			</div>
		);
	}
	if (!blocker?.type) return null;
	const affectedText =
		typeof blocker.affectedAssets === "number" && blocker.affectedAssets > 0
			? `影响资产 ${formatNumber(blocker.affectedAssets)}`
			: undefined;
	const waitText =
		typeof blocker.waitingDurationSeconds === "number"
			? `已等待 ${formatEventDurationSeconds(
					blocker.waitingDurationSeconds * 1000,
				)}`
			: undefined;
	const description = (
		<div>
			<Space size={6} wrap>
				{blocker.nodeName || blocker.nodeKey ? (
					<Tag color="blue">{blocker.nodeName || blocker.nodeKey}</Tag>
				) : null}
				{affectedText ? <Tag color="orange">{affectedText}</Tag> : null}
				{waitText ? <Tag>{waitText}</Tag> : null}
				{blocker.reasons?.slice(0, 3).map((reason) => (
					<Tag key={`${reason.kind}-${reason.message}`} color="gold">
						{reason.kind} ×{reason.count}
					</Tag>
				))}
			</Space>
			{blocker.reasons?.[0]?.message ? (
				<Typography.Text
					style={{ display: "block", marginTop: 6, color: "#475569" }}
				>
					{blocker.reasons[0].message}
				</Typography.Text>
			) : null}
			<Space size={8} wrap style={{ marginTop: 6 }}>
				{blocker.nodeKey ? (
					<Button size="small" onClick={() => onJumpToNode(blocker.nodeKey)}>
						跳转节点明细
					</Button>
				) : null}
				{blocker.actions?.map((action) => (
					<Tag key={action}>{action}</Tag>
				))}
			</Space>
			{blocker.rawMessage ? (
				<details style={{ marginTop: 6 }}>
					<summary style={{ cursor: "pointer", color: "#64748b" }}>
						查看原始错误
					</summary>
					<Typography.Paragraph
						style={{
							marginTop: 6,
							marginBottom: 0,
							whiteSpace: "pre-wrap",
							color: "#334155",
						}}
					>
						{blocker.rawMessage}
					</Typography.Paragraph>
				</details>
			) : null}
		</div>
	);
	return (
		<div style={{ padding: "8px 24px 0", background: "#f8fafc" }}>
			<Alert
				type={blockerAlertType(blocker.severity)}
				showIcon
				message={blocker.title || "当前卡点"}
				description={description}
				style={{ borderRadius: 6 }}
			/>
		</div>
	);
}

function getAssetIdFromOutputEntries(outputEntries: string[]) {
	for (const item of outputEntries) {
		const token = item.split("=")[0]?.trim().toLowerCase();
		if (token === "asset_id" || token === "asset-id") {
			const value = item.split("=").slice(1).join("=").trim();
			if (value) return value;
		}
	}
	const resultPayload = outputEntries.find(
		(item) =>
			item.toLowerCase().includes("asset_id") ||
			item.toLowerCase().includes("asset-id"),
	);
	if (!resultPayload) return null;
	const matched = resultPayload.match(
		/\basset[_-]?id\b\s*[=:]\s*([0-9a-fA-F-]+)/i,
	);
	return matched ? matched[1] : null;
}

function getAssetIdMatchText(outputEntries: string[], runAssetIds: string[]) {
	const assetId = getAssetIdFromOutputEntries(outputEntries);
	if (!assetId) return null;
	if (runAssetIds.length === 0) {
		return {
			value: assetId,
			state: "unbound" as const,
		};
	}
	return {
		value: assetId,
		state: runAssetIds.includes(assetId)
			? ("match" as const)
			: ("mismatch" as const),
	};
}

function WorkflowSummaryCards({
	workflow,
	runEventState,
	costSummaryState,
	runDetailState,
}: {
	workflow: NonNullable<ReturnType<typeof useWorkflowDetail>["workflow"]>;
	runEventState: ReturnType<typeof useWorkflowDetail>["runEventState"];
	costSummaryState: ReturnType<typeof useWorkflowDetail>["costSummaryState"];
	runDetailState: ReturnType<typeof useWorkflowDetail>["runDetailState"];
}) {
	const run = runEventState.run;
	const nodeAggregate = sumNodeSummaries(runDetailState.nodeSummary);
	const templateName =
		run?.templateName ||
		(workflow.labels
			? getWorkflowLabel(workflow.labels, "template-name") ||
				getWorkflowLabel(workflow.labels, "pipeline-name")
			: undefined);
	const templateVersion =
		run?.templateVersion ??
		(workflow.labels
			? Number(getWorkflowLabel(workflow.labels, "template-version"))
			: undefined);
	const assetIds =
		run?.assetIds?.join(",") ||
		(workflow.labels
			? getWorkflowLabel(workflow.labels, "asset-ids") ||
				getWorkflowLabel(workflow.labels, "asset_ids")
			: undefined);
	const assetIdList = assetIds
		? assetIds
				.split(",")
				.map((item) => item.trim())
				.filter(Boolean)
		: [];
	const assetCount = run?.assetCount || assetIdList.length;
	const visibleAssetIds = assetIdList.slice(0, 4);
	const hiddenAssetCount = Math.max(
		assetIdList.length - visibleAssetIds.length,
		0,
	);
	const templateSnapshotId = run?.templateId;
	const triggerSourceLabel = (() => {
		switch (run?.triggerSource) {
			case "manual":
				return "手动运行";
			case "asset_run":
				return "资产运行";
			case "batch":
				return "批量任务";
			case "api":
				return "API 运行";
			default:
				return undefined;
		}
	})();

	const cards = [
		{
			label: "流水线",
			value: templateName || "—",
			extra: templateVersion ? `v${templateVersion}` : undefined,
			meta: [
				templateSnapshotId ? `快照 ${toAssetStyleId(templateSnapshotId)}` : "",
				triggerSourceLabel || "",
			]
				.filter(Boolean)
				.join(" · "),
		},
		{
			label: "资产",
			value:
				assetCount > 0 ? (
					<div style={{ display: "flex", gap: 4, flexWrap: "wrap" }}>
						{visibleAssetIds.map((assetId) => (
							<Link key={assetId} to={`/assets/${encodeURIComponent(assetId)}`}>
								<Tag color="blue" style={{ marginInlineEnd: 0 }}>
									<Tooltip title={assetId}>
										<Typography.Text
											copyable={{ text: assetId }}
											style={{ color: "inherit" }}
										>
											{formatRunIdShort(assetId)}
										</Typography.Text>
									</Tooltip>
								</Tag>
							</Link>
						))}
						{hiddenAssetCount > 0 ? <Tag>+{hiddenAssetCount}</Tag> : null}
						{assetIdList.length === 0 ? formatNumber(assetCount) : null}
					</div>
				) : (
					"无资产"
				),
		},
		...(run?.totalShards
			? [
					{
						label: "任务提交",
						value: `${formatNumber(run.completedShards)}/${formatNumber(
							run.totalShards,
						)}`,
						meta: [
							run.runningShards ? `运行 ${run.runningShards}` : "",
							run.failedShards ? `失败 ${run.failedShards}` : "",
							run.submittedShards ? `已提交 ${run.submittedShards}` : "",
						]
							.filter(Boolean)
							.join(" · "),
					},
				]
			: []),
		{
			label: "节点",
			value: (() => {
				const runtimeCounts = getNodeRuntimeCounts(workflow.nodes);
				const total =
					nodeAggregate.total || run?.totalNodes || runtimeCounts.total;
				const succeeded =
					nodeAggregate.succeeded ||
					run?.completedNodes ||
					runtimeCounts.succeeded;
				if (total === 0) return "0";
				return `${formatNumber(succeeded)}/${formatNumber(total)} 成功`;
			})(),
			meta: (() => {
				const runtimeCounts = getNodeRuntimeCounts(workflow.nodes);
				const failed =
					nodeAggregate.failed || run?.failedNodes || runtimeCounts.failed;
				const running = nodeAggregate.running || runtimeCounts.running;
				const retried = runtimeCounts.retried;
				const total =
					nodeAggregate.total || run?.totalNodes || runtimeCounts.total;
				const details = [
					failed > 0 ? `失败 ${formatNumber(failed)}` : "无失败",
					running > 0 ? `进行中 ${formatNumber(running)}` : "",
					nodeAggregate.queued > 0
						? `排队 ${formatNumber(nodeAggregate.queued)}`
						: "",
					nodeAggregate.cached > 0
						? `缓存 ${formatNumber(nodeAggregate.cached)}`
						: "",
					nodeAggregate.tainted > 0
						? `污染 ${formatNumber(nodeAggregate.tainted)}`
						: "",
					retried > 0 ? `重试 ${formatNumber(retried)}` : "",
					total > 0 ? "已汇总" : "",
				].filter(Boolean);
				return details.join(" · ");
			})(),
		},
		{
			label: "耗时",
			value: (
				<DurationPanel
					phase={workflow.status}
					startedAt={workflow.createdAt}
					finishedAt={workflow.finishedAt}
				/>
			),
		},
		{
			label: "事件",
			value: runEventState.items.length,
			meta:
				runEventState.items.length > 0
					? `${countEventErrors(runEventState.items)} 错误 / ${countEventWarnings(runEventState.items)} 警告`
					: "暂无事件",
		},
		{
			label: "成本",
			value: formatWorkflowSummaryCost(workflow.status, costSummaryState),
		},
	];

	return (
		<div
			style={{
				display: "flex",
				gap: 12,
				padding: "8px 24px",
				borderBottom: "1px solid #e5e7eb",
				background: "#fff",
				flexWrap: "wrap",
			}}
		>
			{cards.map((card) => (
				<div
					key={card.label}
					style={{
						flex: "1 1 100px",
						minWidth: 80,
						padding: "6px 10px",
						background: "#f8fafc",
						borderRadius: 6,
						border: "1px solid #e5e7eb",
					}}
				>
					<div style={{ fontSize: 11, color: "#94a3b8", marginBottom: 2 }}>
						{card.label}
					</div>
					<div style={{ fontSize: 13, fontWeight: 600, color: "#0f172a" }}>
						{card.value}
						{card.extra ? (
							<Tag color="blue" style={{ marginInlineStart: 4, fontSize: 10 }}>
								{card.extra}
							</Tag>
						) : null}
					</div>
					{card.meta ? (
						<div
							style={{
								fontSize: 11,
								color: "#64748b",
								marginTop: 4,
								lineHeight: 1.35,
							}}
						>
							{card.meta}
						</div>
					) : null}
				</div>
			))}
		</div>
	);
}

function dedupeConsecutiveEvents(
	events: PipelineRunEvent[],
): PipelineRunEvent[] {
	const result: PipelineRunEvent[] = [];
	for (const event of events) {
		const last = result[result.length - 1];
		if (
			last &&
			last.eventType === event.eventType &&
			last.subjectType === event.subjectType
		) {
			// Skip duplicate consecutive same-type events (e.g. repeated PodInitializing)
			continue;
		}
		result.push(event);
	}
	return result;
}

function WorkflowRunContextPanel({
	runEventState,
	runEventFilters,
	onFilterEvents,
	onRefreshEvents,
	onLoadMoreEvents,
	onSelectNodeEvent,
}: {
	runEventState: ReturnType<typeof useWorkflowDetail>["runEventState"];
	runEventFilters: ReturnType<typeof useWorkflowDetail>["runEventFilters"];
	onFilterEvents: (
		filters: ReturnType<typeof useWorkflowDetail>["runEventFilters"],
	) => void;
	onRefreshEvents: () => void;
	onLoadMoreEvents: () => void;
	onSelectNodeEvent: (event: PipelineRunEvent) => void;
}) {
	const [expanded, setExpanded] = useState(false);
	const latestEvents = dedupeConsecutiveEvents(runEventState.items).slice(-5);
	const runEventGroups = buildRunEventGroups(latestEvents);
	const errorCount = countEventErrors(runEventState.items);
	const warningCount = countEventWarnings(runEventState.items);

	return (
		<div
			style={{
				margin: "0 24px 12px",
				border: "1px solid #e5e7eb",
				borderRadius: 8,
				background: "#fff",
				overflow: "hidden",
				padding: "8px 10px",
			}}
		>
			<div
				style={{
					display: "flex",
					alignItems: "center",
					gap: 8,
					flexWrap: "wrap",
				}}
			>
				<Typography.Text strong style={{ fontSize: 13 }}>
					事件时间线
				</Typography.Text>
				<Tag>{runEventState.items.length}</Tag>
				{errorCount > 0 ? <Tag color="red">错误 {errorCount}</Tag> : null}
				{warningCount > 0 ? (
					<Tag color="orange">警告 {warningCount}</Tag>
				) : null}
				<Button
					size="small"
					type="link"
					onClick={() => setExpanded((value) => !value)}
				>
					{expanded ? "收起" : "展开"}
				</Button>
				<Button
					size="small"
					icon={<ReloadOutlined />}
					loading={runEventState.loading}
					onClick={onRefreshEvents}
				>
					刷新
				</Button>
			</div>
			{expanded ? (
				<>
					<div
						style={{
							display: "flex",
							alignItems: "center",
							gap: 8,
							marginTop: 8,
							marginBottom: 8,
							flexWrap: "wrap",
						}}
					>
						<Select
							size="small"
							placeholder="事件类型"
							allowClear
							style={{ width: 130 }}
							value={runEventFilters.eventType}
							onChange={(val) =>
								onFilterEvents({ ...runEventFilters, eventType: val })
							}
							options={Object.entries(RUN_EVENT_LABELS).map(([key, label]) => ({
								label,
								value: key,
							}))}
						/>
						<Select
							size="small"
							placeholder="状态"
							allowClear
							style={{ width: 100 }}
							value={runEventFilters.status}
							onChange={(val) =>
								onFilterEvents({ ...runEventFilters, status: val })
							}
							options={["Succeeded", "Failed", "Error", "Running"].map((s) => ({
								label: s,
								value: s,
							}))}
						/>
						<Input.Search
							id="workflow-event-search"
							name="workflowEventSearch"
							size="small"
							placeholder="搜索消息/ID"
							allowClear
							style={{ width: 180 }}
							value={runEventFilters.q}
							onChange={(event) =>
								onFilterEvents({ ...runEventFilters, q: event.target.value })
							}
							onSearch={() => onRefreshEvents()}
						/>
					</div>
					{runEventState.error ? (
						<Alert
							type="info"
							showIcon
							message="事件暂不可用"
							description={`这是历史工作流或外部提交的工作流，暂时没有 DataBrew 运行事件。${formatRunEventError(runEventState.error)}`}
							style={{ marginBottom: 8 }}
						/>
					) : null}
					{runEventState.loading &&
					latestEvents.length === 0 &&
					!runEventState.error ? (
						<Spin size="small" />
					) : latestEvents.length === 0 && !runEventState.error ? (
						<Typography.Text type="secondary">暂无运行事件</Typography.Text>
					) : (
						<div
							style={{ display: "grid", gap: 10 }}
							className="workflow-run-event-groups"
						>
							{runEventGroups.map((group) => (
								<div
									key={`${group.stage}-${group.totalMs}`}
									style={{
										border: "1px solid #e5e7eb",
										borderRadius: 6,
										padding: 6,
									}}
								>
									<div style={{ marginBottom: 6 }}>
										<Typography.Text strong>
											{RUN_EVENT_STAGE_LABELS[group.stage]}
										</Typography.Text>
										<Typography.Text type="secondary" style={{ marginLeft: 6 }}>
											耗时 {formatEventDurationSeconds(group.totalMs)}
										</Typography.Text>
									</div>
									<div style={{ display: "grid", gap: 6 }}>
										{group.events.map(({ event, durationMs }) => (
											<button
												key={event.id}
												type="button"
												onClick={() => onSelectNodeEvent(event)}
												disabled={event.subjectType !== "node"}
												className={
													event.subjectType === "node"
														? "workflow-run-event"
														: "workflow-run-event workflow-run-event--static"
												}
											>
												<div
													style={{
														display: "flex",
														alignItems: "center",
														gap: 6,
													}}
												>
													<Tag
														color={eventTagColor(event)}
														style={{ fontSize: 10 }}
													>
														{RUN_EVENT_LABELS[event.eventType] ||
															event.eventType}
													</Tag>
													<Typography.Text strong style={{ fontSize: 12 }}>
														{shortEventSubject(event)}
													</Typography.Text>
													<Typography.Text
														type="secondary"
														style={{ fontSize: 10 }}
													>
														{formatEventTime(event.occurredAt)}
													</Typography.Text>
													{durationMs ? (
														<Typography.Text
															type="secondary"
															style={{ fontSize: 10, marginLeft: "auto" }}
														>
															+{formatEventDurationSeconds(durationMs)}
														</Typography.Text>
													) : null}
												</div>
												{event.message ? (
													<Typography.Text
														type="secondary"
														style={{
															display: "block",
															marginTop: 2,
															fontSize: 11,
														}}
														ellipsis={{ tooltip: event.message }}
													>
														{event.message}
													</Typography.Text>
												) : null}
											</button>
										))}
									</div>
								</div>
							))}
						</div>
					)}
					{runEventState.nextCursor ? (
						<Button
							size="small"
							type="link"
							onClick={onLoadMoreEvents}
							style={{ marginTop: 6 }}
						>
							加载更多事件
						</Button>
					) : null}
				</>
			) : runEventState.error ? (
				<Typography.Text type="secondary" style={{ fontSize: 12 }}>
					事件暂不可用
				</Typography.Text>
			) : latestEvents.length > 0 ? (
				<Typography.Text type="secondary" style={{ fontSize: 12 }}>
					最近事件：
					{RUN_EVENT_LABELS[
						latestEvents[latestEvents.length - 1]?.eventType || ""
					] ||
						latestEvents[latestEvents.length - 1]?.eventType ||
						"-"}
				</Typography.Text>
			) : (
				<Typography.Text type="secondary" style={{ fontSize: 12 }}>
					暂无运行事件
				</Typography.Text>
			)}
		</div>
	);
}

