const OVERFLOW_OPERATION_KEYS: ReadonlySet<WorkflowOperationKey> = new Set([
	"stop",
	"suspend",
	"terminate",
	"delete",
	"resubmit",
]);

function formatCost(value?: number | null) {
	if (typeof value !== "number") return "成本快照未生成";
	if (value < 0.01) return `$${value.toFixed(4)}`;
	return `$${value.toFixed(2)}`;
}

function formatCostSource(value?: string) {
	if (value === "estimated_resource_duration") return "估算";
	if (value === "not_available") return "成本暂不可用";
	return "成本快照未生成";
}

const COST_WAITING_STATUSES = new Set([
	"pending",
	"running",
	"waiting",
	"queued",
]);
const COST_TERMINAL_STATUSES = new Set([
	"succeeded",
	"failed",
	"error",
	"skipped",
	"omitted",
	"terminated",
	"stopped",
]);

function normalizeStatus(value?: string) {
	return (value || "").trim().toLowerCase();
}

function isWaitingForRuntimeResources(status?: string) {
	return COST_WAITING_STATUSES.has(normalizeStatus(status));
}

function isTerminalCostStatus(status?: string) {
	return COST_TERMINAL_STATUSES.has(normalizeStatus(status));
}

function workflowNodeLookupKeys(node: WorkflowNodeStatus): string[] {
	return [
		node.id,
		node.name,
		node.displayName,
		node.templateName,
		node.name?.split(".").pop(),
	]
		.map((value) => value?.trim())
		.filter((value): value is string => !!value);
}

function buildWorkflowNodeLookup(nodes: WorkflowNodeStatus[]) {
	const lookup = new Map<string, WorkflowNodeStatus>();
	for (const node of nodes) {
		for (const key of workflowNodeLookupKeys(node)) {
			if (!lookup.has(key)) {
				lookup.set(key, node);
			}
		}
	}
	return lookup;
}

function findLiveWorkflowNode(
	lookup: Map<string, WorkflowNodeStatus>,
	row: {
		argoNodeId?: string;
		pipelineNodeId?: string;
		nodeId?: string;
		displayName?: string;
	},
) {
	const candidates = [
		row.argoNodeId,
		row.pipelineNodeId,
		row.nodeId,
		row.displayName,
	]
		.map((value) => value?.trim())
		.filter((value): value is string => !!value);
	for (const candidate of candidates) {
		const direct = lookup.get(candidate);
		if (direct) return direct;
		const suffix = candidate.split(".").pop();
		if (suffix) {
			const bySuffix = lookup.get(suffix);
			if (bySuffix) return bySuffix;
		}
	}
	return null;
}

function canOpenWorkflowNodeLogs(node: WorkflowNodeStatus | null | undefined) {
	if (!node) return false;
	if (node.debug?.logStreamEnabled === false && !node.podName) return false;
	return Boolean(node.id);
}

function getAssetNodeTechnicalLabel(row: PipelineRunAssetNode) {
	const candidates = [row.pipelineNodeId, row.argoNodeId, row.displayName]
		.map((value) => value?.trim())
		.filter((value): value is string => !!value);
	return candidates.find((value, index) => candidates.indexOf(value) === index);
}

function isArgoControlAssetNode(row: PipelineRunAssetNode) {
	const pipelineNodeId = row.pipelineNodeId?.trim() || "";
	const displayName = row.displayName?.trim() || "";
	const isIndexedControl =
		/^\[\d+\]$/.test(pipelineNodeId) || /^\[\d+\]$/.test(displayName);
	return isIndexedControl && !row.podName && !row.logRef;
}

function getAssetNodeRetryCount(
	row: PipelineRunAssetNode | WorkflowNodeStatus,
) {
	const candidate = row.message || "";
	const matched = /retry\s*(\d+)/i.exec(candidate);
	if (!matched) return 0;
	return Number.parseInt(matched[1], 10) || 0;
}

function getAssetNodeOutputs(
	row: PipelineRunAssetNode,
	nodeLookup: Map<string, WorkflowNodeStatus>,
) {
	const liveNode = findLiveWorkflowNode(nodeLookup, row);
	const outputEntries = liveNode
		? formatBusinessOutputSummary(liveNode)
		: row.assetId && row.assetId !== "no-asset"
			? [`asset_id=${row.assetId}`]
			: [];
	return outputEntries;
}

function formatAssetNodeOutputs(
	row: PipelineRunAssetNode,
	nodeLookup: Map<string, WorkflowNodeStatus>,
) {
	const outputEntries = getAssetNodeOutputs(row, nodeLookup);
	return outputEntries.map((item) => (
		<Tooltip key={item} title={item}>
			<Typography.Text
				type="secondary"
				ellipsis={{ tooltip: item }}
				style={{ maxWidth: 180, display: "inline-block" }}
			>
				{item}
			</Typography.Text>
		</Tooltip>
	));
}

function getAssetNodeRetryText(row: PipelineRunAssetNode) {
	const retryCount = getAssetNodeRetryCount(row);
	return retryCount > 0 ? `${retryCount}` : "0";
}

function shouldUseLiveWorkflowStatus(rowStatus?: string, liveStatus?: string) {
	return (
		isWaitingForRuntimeResources(rowStatus) && isTerminalCostStatus(liveStatus)
	);
}

function rowMissingCost(row: {
	estimatedCostUsd?: number | null;
	status?: string;
}) {
	return typeof row.estimatedCostUsd !== "number";
}

function costSnapshotMessage(row: {
	estimatedCostUsd?: number | null;
	status?: string;
}) {
	if (typeof row.estimatedCostUsd === "number") {
		return "估算成本，非 GCP Billing 最终账单";
	}
	if (isWaitingForRuntimeResources(row.status)) {
		return "待计算，节点运行后生成估算成本";
	}
	if (isTerminalCostStatus(row.status)) {
		return "成本快照未生成，当前没有可展示的估算成本";
	}
	return "成本快照未生成";
}

function formatCostCellValue(row: {
	estimatedCostUsd?: number | null;
	status?: string;
}) {
	if (typeof row.estimatedCostUsd === "number") {
		return formatCost(row.estimatedCostUsd);
	}
	if (isWaitingForRuntimeResources(row.status)) {
		return "待计算";
	}
	if (isTerminalCostStatus(row.status)) {
		return "成本快照未生成";
	}
	return "成本快照未生成";
}

function formatWorkflowSummaryCost(
	workflowStatus: string,
	costSummaryState: ReturnType<typeof useWorkflowDetail>["costSummaryState"],
) {
	const total = costSummaryState.item?.totalEstimatedCostUsd;
	if (typeof total === "number") {
		return `~$${total.toFixed(4)}`;
	}
	if (costSummaryState.loading) {
		return "同步中";
	}
	if (costSummaryState.error) {
		return "成本暂不可用";
	}
	if (isWaitingForRuntimeResources(workflowStatus)) {
		return "待计算";
	}
	if (isTerminalCostStatus(workflowStatus)) {
		return "成本快照未生成";
	}
	if (costSummaryState.item?.costSource === "not_available") {
		return "成本暂不可用";
	}
	return "成本快照未生成";
}

export function getWorkflowLogEmptyState(
	node?: Pick<WorkflowNodeStatus, "phase" | "message"> | null,
) {
	if (!node) {
		return {
			message: "暂无日志",
			description: "当前节点暂未返回可展示的日志内容。",
		};
	}
	if (isWaitingForRuntimeResources(node.phase)) {
		return {
			message: "等待日志输出",
			description: node.message
				? `节点还在调度、排队或启动中；开始运行后会逐步输出日志。当前状态：${node.message}`
				: "节点还在调度、排队或启动中；开始运行后会逐步输出日志。",
		};
	}
	if (isTerminalCostStatus(node.phase)) {
		return {
			message: "暂无日志输出",
			description:
				"这个步骤没有返回可展示的日志内容；可继续查看 Pod 事件、节点消息和运行环境。",
		};
	}
	return {
		message: "暂无日志",
		description: "当前节点暂未返回可展示的日志内容。",
	};
}

function getWorkflowLogPaginationDescription(
	node?: Pick<WorkflowNodeStatus, "phase"> | null,
	serverReason?: string,
) {
	if (serverReason && !/live argo logs/i.test(serverReason)) {
		return serverReason;
	}
	if (node && isWaitingForRuntimeResources(node.phase)) {
		return "当前展示的是实时日志窗口，历史翻页暂不可用。节点开始运行后可继续实时查看、刷新或下载当前窗口。";
	}
	return "当前展示的是实时日志窗口，历史翻页暂不可用。可继续实时查看、刷新或下载当前窗口。";
}

export function formatWorkflowLogError(
	node: Pick<WorkflowNodeStatus, "phase" | "message"> | null,
	error?: string | null,
) {
	const raw = error?.trim() || "";
	if (/live argo logs|stable historical cursor|cursor pagination/i.test(raw)) {
		return getWorkflowLogPaginationDescription(node, raw);
	}
	if (node && isWaitingForRuntimeResources(node.phase)) {
		return node.message
			? `节点还未开始运行，日志将在 Pod 启动后生成。当前状态：${node.message}`
			: "节点还未开始运行，日志将在 Pod 启动后生成；可先查看事件和运行环境。";
	}
	if (/pod.*not.*found|container.*not.*found|not found/i.test(raw)) {
		return "日志暂不可用，Pod 或容器还没有准备好；可先查看事件和运行环境。";
	}
	if (raw && !/[\u4e00-\u9fff]/.test(raw) && /[a-z]/i.test(raw)) {
		return "日志暂不可用，请稍后重试，或查看事件和运行环境。";
	}
	return raw || "日志暂不可用，请稍后重试，或查看事件和运行环境。";
}

function formatDurationSeconds(startedAt?: string, finishedAt?: string) {
	if (!startedAt || !finishedAt) return "-";
	const start = new Date(startedAt).getTime();
	const end = new Date(finishedAt).getTime();
	if (Number.isNaN(start) || Number.isNaN(end) || end < start) return "-";
	const seconds = Math.round((end - start) / 1000);
	if (seconds < 60) return `${seconds}s`;
	const minutes = Math.floor(seconds / 60);
	return `${minutes}m ${seconds % 60}s`;
}

function WorkflowAssetNodePanel({
	assetNodeState,
	runAssetIds,
	costSummaryState,
	workflowNodeCount,
	workflowNodes,
	onSelectAssetNode,
}: {
	assetNodeState: ReturnType<typeof useWorkflowDetail>["assetNodeState"];
	runAssetIds: string[];
	costSummaryState: ReturnType<typeof useWorkflowDetail>["costSummaryState"];
	workflowNodeCount: number;
	workflowNodes: WorkflowNodeStatus[];
	onSelectAssetNode: (
		row: PipelineRunAssetNode,
		action: WorkflowDagNodeAction,
	) => void;
}) {
	const liveWorkflowNodeByKey = useMemo(
		() => buildWorkflowNodeLookup(workflowNodes),
		[workflowNodes],
	);
	const displayAssetNodeItems = useMemo(
		() =>
			assetNodeState.items
				.filter((row) => !isArgoControlAssetNode(row))
				.map((row) => {
					const liveNode = findLiveWorkflowNode(liveWorkflowNodeByKey, row);
					const liveDisplayName =
						liveNode && row.pipelineNodeId !== "dag"
							? getWorkflowNodeDisplayText(liveNode)
							: undefined;
					const displayRow =
						liveDisplayName && liveDisplayName !== row.displayName
							? { ...row, displayName: liveDisplayName }
							: row;
					if (
						!liveNode ||
						!shouldUseLiveWorkflowStatus(row.status, liveNode.phase)
					) {
						return displayRow;
					}
					return {
						...displayRow,
						status: liveNode.phase,
						message: liveNode.message ?? row.message,
						podName: liveNode.podName ?? row.podName,
						startedAt: liveNode.startedAt ?? row.startedAt,
						finishedAt: liveNode.finishedAt ?? row.finishedAt,
						estimatedCostUsd: liveNode.estimatedCostUsd ?? row.estimatedCostUsd,
					};
				}),
		[assetNodeState.items, liveWorkflowNodeByKey],
	);
	const displayCostSummaryRows = useMemo(
		() =>
			(costSummaryState.item?.nodeSummaries ?? []).map((row) => {
				const liveNode = findLiveWorkflowNode(liveWorkflowNodeByKey, {
					nodeId: row.nodeId,
					displayName: row.displayName,
				});
				if (
					!liveNode ||
					!shouldUseLiveWorkflowStatus(row.status, liveNode.phase)
				) {
					return row;
				}
				return {
					...row,
					status: liveNode.phase,
					estimatedCostUsd: liveNode.estimatedCostUsd ?? row.estimatedCostUsd,
				};
			}),
		[costSummaryState.item?.nodeSummaries, liveWorkflowNodeByKey],
	);
	const summary = assetNodeState.summary;
	const noAssetOnly =
		displayAssetNodeItems.length > 0 &&
		displayAssetNodeItems.every((row) => row.assetId === "no-asset");
	const displayAssetCount = noAssetOnly ? "无资产" : (summary?.assetCount ?? 0);
	const totalEstimatedCost =
		costSummaryState.item?.totalEstimatedCostUsd ??
		summary?.totalEstimatedCostUsd;
	const costSource = costSummaryState.item?.costSource ?? summary?.costSource;
	const expectedNodeCount = workflowNodeCount || summary?.nodeCount || 0;
	const syncedNodeCount = costSummaryState.item?.nodeSummaries?.length ?? 0;
	const syncedAssetNodeCount =
		costSummaryState.item?.assetNodeSummaries?.length ?? 0;
	const assetBusinessRows = displayAssetNodeItems.filter(
		(row) => row.pipelineNodeId !== "dag",
	);
	const allCostRows = [...assetBusinessRows, ...displayCostSummaryRows];
	const waitingForResourceSnapshot =
		!costSummaryState.loading &&
		totalEstimatedCost == null &&
		allCostRows.some(
			(row) => rowMissingCost(row) && isWaitingForRuntimeResources(row.status),
		);
	const completedMissingCost =
		!costSummaryState.loading &&
		totalEstimatedCost == null &&
		allCostRows.length > 0 &&
		!waitingForResourceSnapshot &&
		allCostRows.every((row) => rowMissingCost(row)) &&
		allCostRows.some((row) => isTerminalCostStatus(row.status));
	const hasCostRows =
		syncedNodeCount > 0 ||
		syncedAssetNodeCount > 0 ||
		displayAssetNodeItems.length > 0;
	const costUnavailable =
		!costSummaryState.loading &&
		costSource === "not_available" &&
		hasCostRows &&
		totalEstimatedCost == null &&
		!waitingForResourceSnapshot &&
		!completedMissingCost;
	const costSyncPartial =
		!costUnavailable &&
		!waitingForResourceSnapshot &&
		!completedMissingCost &&
		expectedNodeCount > 0 &&
		syncedNodeCount > 0 &&
		syncedNodeCount < expectedNodeCount;
	const costSyncPending =
		costSummaryState.loading ||
		(!waitingForResourceSnapshot &&
			!completedMissingCost &&
			expectedNodeCount > 0 &&
			!hasCostRows &&
			totalEstimatedCost == null);
	const costStateLabel = costSyncPending
		? "同步中"
		: waitingForResourceSnapshot
			? "待计算"
			: completedMissingCost || costUnavailable
				? completedMissingCost
					? "成本快照未生成"
					: "成本暂不可用"
				: formatCost(totalEstimatedCost);
	const costSourceLabel = costSyncPending
		? "同步中"
		: costSyncPartial
			? `部分同步 ${syncedNodeCount}/${expectedNodeCount}`
			: waitingForResourceSnapshot
				? "待计算"
				: completedMissingCost
					? "成本快照未生成"
					: formatCostSource(costSource);
	const costTagColor =
		costSyncPending || costSyncPartial || waitingForResourceSnapshot
			? "orange"
			: completedMissingCost || costUnavailable
				? "default"
				: "blue";
	const shouldShowAssetColumn =
		!noAssetOnly &&
		new Set(
			displayAssetNodeItems
				.map((row) => row.assetId)
				.filter((value) => value !== "no-asset"),
		).size > 1;
	const columns: NonNullable<TableProps<PipelineRunAssetNode>["columns"]> = [
		...(shouldShowAssetColumn
			? [
					{
						title: "资产",
						dataIndex: "assetId",
						width: 170,
						render: (value: string) => (
							<Tag color={value === "no-asset" ? "default" : "blue"}>
								{value === "no-asset" ? "无资产" : value}
							</Tag>
						),
					},
				]
			: []),
		{
			title: "节点",
			dataIndex: "displayName",
			render: (
				_: PipelineRunAssetNode["displayName"],
				row: PipelineRunAssetNode,
			) => {
				if (row.pipelineNodeId === "dag") return "运行汇总";
				const label = row.displayName || row.pipelineNodeId || "-";
				const technicalLabel = getAssetNodeTechnicalLabel(row);
				if (!technicalLabel || technicalLabel === label) return label;
				return (
					<Tooltip title={`技术 ID: ${technicalLabel}`}>
						<span>{label}</span>
					</Tooltip>
				);
			},
		},
		{
			title: "状态",
			dataIndex: "status",
			width: 120,
			render: (value: PipelineRunAssetNode["status"]) => (
				<Tag
					color={eventTagColor({
						status: value,
						eventType: value,
					} as PipelineRunEvent)}
				>
					{value || "-"}
				</Tag>
			),
		},
		{
			title: "耗时",
			width: 100,
			render: (
				_: PipelineRunAssetNode["startedAt"],
				row: PipelineRunAssetNode,
			) => formatDurationSeconds(row.startedAt, row.finishedAt),
		},
		{
			title: "输出",
			key: "outputs",
			render: (_: unknown, row: PipelineRunAssetNode) => {
				if (row.pipelineNodeId === "dag") {
					return <Typography.Text type="secondary">运行汇总</Typography.Text>;
				}
				const outputEntries = getAssetNodeOutputs(row, liveWorkflowNodeByKey);
				const hasOutputEntries =
					outputEntries.length > 0 ||
					!!getAssetIdMatchText(outputEntries, runAssetIds);
				const outputValidation = getAssetIdMatchText(
					outputEntries,
					runAssetIds,
				);
				const outputs = formatAssetNodeOutputs(row, liveWorkflowNodeByKey);
				return hasOutputEntries ? (
					<Space direction="vertical" size={2}>
						{outputs}
						{outputValidation ? (
							<Tag
								color={
									outputValidation.state === "match"
										? "green"
										: outputValidation.state === "mismatch"
											? "red"
											: "default"
								}
							>
								{outputValidation.state === "match"
									? `校验通过: ${outputValidation.value}`
									: outputValidation.state === "mismatch"
										? `校验失败: ${outputValidation.value}`
										: `校验不可验证: ${outputValidation.value}`}
							</Tag>
						) : null}
					</Space>
				) : null;
			},
		},
		{
			title: "重试",
			width: 64,
			dataIndex: "message",
			render: (_: PipelineRunAssetNode["message"], row: PipelineRunAssetNode) =>
				getAssetNodeRetryText(row),
		},
		{
			title: "估算成本",
			width: 120,
			render: (
				_: PipelineRunAssetNode["status"],
				row: PipelineRunAssetNode,
			) => (
				<Tooltip title={costSnapshotMessage(row)}>
					<span>{formatCostCellValue(row)}</span>
				</Tooltip>
			),
		},
		{
			title: "操作",
			width: 190,
			render: (
				_: PipelineRunAssetNode["status"],
				row: PipelineRunAssetNode,
			) => {
				const liveNode = findLiveWorkflowNode(liveWorkflowNodeByKey, row);
				const podName = liveNode?.podName || row.podName;
				const actions = [
					<Button
						key="summary"
						size="small"
						type="link"
						onClick={() => onSelectAssetNode(row, "summary")}
					>
						详情
					</Button>,
				];
				const shouldShowLogAction =
					row.logRef ||
					Boolean(liveNode?.id && podName) ||
					(() => {
						const status = (row.status || "").toLowerCase();
						return ["failed", "error", "terminated", "stopped"].includes(
							status,
						);
					})();
				if (shouldShowLogAction) {
					actions.push(
						<Button
							key="logs"
							size="small"
							type="link"
							onClick={() => onSelectAssetNode(row, "logs")}
						>
							日志
						</Button>,
					);
				}
				if (podName) {
					actions.push(
						<Button
							key="pod"
							size="small"
							type="link"
							onClick={() => onSelectAssetNode(row, "runtime")}
						>
							Pod
						</Button>,
						<Button
							key="monitoring"
							size="small"
							type="link"
							onClick={() => onSelectAssetNode(row, "monitoring")}
						>
							监控
						</Button>,
					);
				}
				return <Space size={6}>{actions}</Space>;
			},
		},
	];
	return (
		<div
			style={{
				margin: "0 24px 12px",
				border: "1px solid #e5e7eb",
				borderRadius: 8,
				background: "#fff",
				overflow: "hidden",
			}}
		>
			<div
				style={{
					display: "flex",
					alignItems: "center",
					justifyContent: "space-between",
					gap: 12,
					padding: "8px 10px",
					borderBottom: "1px solid #e5e7eb",
				}}
			>
				<div>
					<Typography.Text strong>节点明细</Typography.Text>
					<Typography.Text
						type="secondary"
						style={{ display: "block", fontSize: 12 }}
					>
						状态、输出、日志、Pod、监控。
					</Typography.Text>
				</div>
				<Space wrap size={12}>
					<Typography.Text type="secondary">
						资产 {displayAssetCount}
					</Typography.Text>
					<Typography.Text type="secondary">
						节点 {expectedNodeCount}
					</Typography.Text>
					<Typography.Text type="secondary">
						总成本 {costStateLabel}
					</Typography.Text>
					<Tag color={costTagColor}>{costSourceLabel}</Tag>
				</Space>
			</div>
			{costSyncPending || costSyncPartial ? (
				<Alert
					type="info"
					showIcon
					message="成本快照仍在同步"
					style={{ margin: "8px 10px 0" }}
				/>
			) : waitingForResourceSnapshot ? (
				<Alert
					type="info"
					showIcon
					message="待计算"
					style={{ margin: "8px 10px 0" }}
				/>
			) : completedMissingCost ? (
				<Alert
					type="info"
					showIcon
					message="成本快照未生成"
					style={{ margin: "8px 10px 0" }}
				/>
			) : costUnavailable ? (
				<Alert
					type="warning"
					showIcon
					message="成本数据暂不可用"
					style={{ margin: "8px 10px 0" }}
				/>
			) : null}
			<Table<PipelineRunAssetNode>
				size="small"
				rowKey="id"
				loading={assetNodeState.loading}
				dataSource={displayAssetNodeItems}
				pagination={
					displayAssetNodeItems.length > 10
						? { pageSize: 10, size: "small", showSizeChanger: false }
						: false
				}
				locale={{
					emptyText: assetNodeState.error || "暂无资产节点明细",
				}}
				columns={columns}
			/>
		</div>
	);
}

export default function WorkflowDetailPage({
	legacyRoute = false,
}: {
	legacyRoute?: boolean;
}) {
	const { message: messageApi } = App.useApp();
	const { name } = useParams<{ name: string }>();
	const [searchParams] = useSearchParams();
	const runId = searchParams.get("runId")?.trim() || undefined;
	const queryShardId = searchParams.get("shardId")?.trim() || undefined;
	const parentRunId = searchParams.get("parentRunId")?.trim() || undefined;
	const taskAssetId = searchParams.get("assetId")?.trim() || undefined;
	const taskNodeKey = searchParams.get("nodeKey")?.trim() || undefined;
	const pendingTaskRouteUsesParentRun = Boolean(
		taskAssetId &&
			parentRunId &&
			queryShardId &&
			(!runId || runId === queryShardId || runId === parentRunId),
	);
	const detailRunId = pendingTaskRouteUsesParentRun ? parentRunId : runId;
	const taskShardRunId = pendingTaskRouteUsesParentRun
		? undefined
		: runId || queryShardId || undefined;
	const navigate = useNavigate();
	const [viewMode, setViewMode] = useState<"dag" | "timeline">("dag");
	const [operationLoading, setOperationLoading] =
		useState<WorkflowOperationKey | null>(null);
	const [retryingNodeId, setRetryingNodeId] = useState<string | null>(null);
	const [confirmOperation, setConfirmOperation] =
		useState<WorkflowOperationConfig | null>(null);
	const [nodeDetailTab, setNodeDetailTab] =
		useState<WorkflowNodeDetailTabKey>("summary");
	const [nodePanelOpen, setNodePanelOpen] = useState(false);
	const [terminalNode, setTerminalNode] = useState<WorkflowNodeStatus | null>(
		null,
	);

	const {
		workflow: liveWorkflow,
		loading,
		loadError,
		statusSyncWarning,
		selectedNode: liveSelectedNode,
		selectNode,
		loadWorkflow,
		logState,
		runEventState,
		runEventFilters,
		setRunEventFilters,
		loadRunEvents,
		assetNodeState,
		costSummaryState,
		runDetailState,
		setLogSearch,
		startFollowLogs,
		stopFollowLogs,
		downloadLogs,
	} = useWorkflowDetail(name, detailRunId, {
		skipAssetNodes: Boolean(taskAssetId),
		skipLiveWorkflow: Boolean(taskAssetId && parentRunId),
	});
	const [taskAssetNodeState, setTaskAssetNodeState] = useState<
		ReturnType<typeof useWorkflowDetail>["assetNodeState"]
	>(() => emptyAssetNodeState());
	useEffect(() => {
		if (!taskAssetId || !taskShardRunId) {
			setTaskAssetNodeState(emptyAssetNodeState());
			return;
		}
		let cancelled = false;
		setTaskAssetNodeState(emptyAssetNodeState(true));
		Promise.all([
			listPipelineRunAssetNodes(taskShardRunId, {
				assetId: taskAssetId,
				limit: 20,
			}),
			listPipelineRunEvents(taskShardRunId, {
				limit: 50,
				q: taskAssetId,
			}),
		])
			.then(([assetNodeResult, eventResult]) => {
				if (cancelled) return;
				const items = overlayTaskRuntimeEvent(
					assetNodeResult.items,
					eventResult.items,
					taskShardRunId,
					taskAssetId,
					taskNodeKey,
				);
				setTaskAssetNodeState({
					items,
					total: Math.max(assetNodeResult.total, items.length),
					loading: false,
					error: null,
					summary: assetNodeResult.summary,
				});
			})
			.catch((err) => {
				if (cancelled) return;
				setTaskAssetNodeState(emptyAssetNodeState(false, String(err)));
			});
		return () => {
			cancelled = true;
		};
	}, [taskAssetId, taskNodeKey, taskShardRunId]);
	const [localSelectedNode, setLocalSelectedNode] =
		useState<WorkflowNodeStatus | null>(null);
	const fallbackWorkflow = useMemo(
		() =>
			taskAssetId
				? buildLedgerWorkflowFallback({
						run: runEventState.run,
						name,
						taskAssetId,
						taskNodeKey,
						nodeSummaries: runDetailState.nodeSummary.map((summary) =>
							nodeSummaryForOneTask(summary, runEventState.run?.status),
						),
						loadMessage:
							loadError?.kind === "not_found" ? loadError.message : undefined,
					})
				: null,
		[
			loadError?.kind,
			loadError?.message,
			name,
			runDetailState.nodeSummary,
			runEventState.run,
			taskAssetId,
			taskNodeKey,
		],
	);
	const workflow = useMemo(
		() => taskScopedWorkflow(liveWorkflow, fallbackWorkflow, taskAssetId),
		[fallbackWorkflow, liveWorkflow, taskAssetId],
	);
	const displayRunEventState = useMemo(
		() => taskScopedRunEventState(runEventState, taskAssetId),
		[runEventState, taskAssetId],
	);
	const displayRunDetailState = useMemo(
		() => taskScopedRunDetailState(runDetailState, workflow, taskAssetId),
		[runDetailState, taskAssetId, workflow],
	);
	const displayAssetNodeState = useMemo(
		() =>
			buildTaskFallbackAssetNodeState({
				base: taskAssetId
					? mergeTaskAssetNodeState(assetNodeState, taskAssetNodeState)
					: assetNodeState,
				run: displayRunEventState.run,
				taskAssetId,
				taskNodeKey,
				workflow,
			}),
		[
			assetNodeState,
			displayRunEventState.run,
			taskAssetNodeState,
			taskAssetId,
			taskNodeKey,
			workflow,
		],
	);
	const resolveTaskRuntimeNode = useCallback(
		(node: WorkflowNodeStatus | null): WorkflowNodeStatus | null => {
			if (!node || !taskAssetId || !workflow) return node;
			const row = displayAssetNodeState.items.find(
				(item) =>
					item.assetId === taskAssetId &&
					Boolean(item.argoNodeId || item.podName || item.logRef) &&
					assetRowMatchesWorkflowNode(item, node, taskNodeKey),
			);
			if (!row) return node;
			return taskRuntimeNodeFromAssetRow(row, workflow.name, taskNodeKey, node);
		},
		[displayAssetNodeState.items, taskAssetId, taskNodeKey, workflow],
	);
	const selectedNode = useMemo(
		() => resolveTaskRuntimeNode(liveSelectedNode ?? localSelectedNode),
		[liveSelectedNode, localSelectedNode, resolveTaskRuntimeNode],
	);
	const workflowNodesForGraph = useMemo(
		() =>
			workflow?.nodes.map((node) => resolveTaskRuntimeNode(node) ?? node) ?? [],
		[resolveTaskRuntimeNode, workflow?.nodes],
	);
	const [showNodeLogs, setShowNodeLogs] = useState(false);
	const operations = useMemo(
		() => (liveWorkflow ? getWorkflowOperationConfigs(liveWorkflow) : []),
		[liveWorkflow],
	);
	const availableOperations = useMemo(
		() =>
			liveWorkflow ? getAvailableWorkflowOperationConfigs(liveWorkflow) : [],
		[liveWorkflow],
	);
	const filteredAvailableOperations = useMemo(() => {
		if (!liveWorkflow) return [];
		const nodePhases = liveWorkflow.nodes
			.filter((n) => n.type !== "DAG")
			.map((n) => n.phase);
		const allTerminal =
			nodePhases.length > 0 &&
			nodePhases.every((p) =>
				["Failed", "Error", "Succeeded", "Skipped", "Omitted"].includes(p),
			);
		const terminalHidden = new Set(["stop", "suspend", "terminate"]);
		return availableOperations.filter(
			(op) => !(allTerminal && terminalHidden.has(op.key)),
		);
	}, [availableOperations, liveWorkflow]);
	const quickOperations = useMemo(
		() =>
			filteredAvailableOperations.filter(
				(op) =>
					!OVERFLOW_OPERATION_KEYS.has(op.key) &&
					!op.danger &&
					op.key !== "delete",
			),
		[filteredAvailableOperations],
	);
	const overflowOperations = useMemo(
		() =>
			filteredAvailableOperations.filter(
				(op) =>
					OVERFLOW_OPERATION_KEYS.has(op.key) ||
					Boolean(op.danger) ||
					op.key === "delete",
			),
		[filteredAvailableOperations],
	);
	const overflowOperationItems = useMemo((): NonNullable<
		MenuProps["items"]
	> => {
		return overflowOperations.map((op) => ({
			key: op.key,
			icon: op.icon,
			label: (
				<div>
					<div>{op.title}</div>
					{op.description ? (
						<div style={{ fontSize: 12, color: "#64748b" }}>
							{op.description}
						</div>
					) : null}
				</div>
			),
			danger: op.danger,
		}));
	}, [overflowOperations]);
	const canRetryWorkflow = useMemo(
		() => operations.some((op) => op.key === "retry" && !op.disabled),
		[operations],
	);
	const workflowAssetIds = useMemo(() => {
		if (taskAssetId) return [taskAssetId];
		return workflow
			? getRunAssetIds(workflow, displayRunEventState.run?.assetIds)
			: [];
	}, [displayRunEventState.run?.assetIds, taskAssetId, workflow]);
	const [selectedNodeAssetId, setSelectedNodeAssetId] = useState<string | null>(
		null,
	);
	const nodeSelectionScopeKey = `${name ?? ""}::${runId ?? ""}::${taskAssetId ?? ""}`;
	const resetLocalNodeSelectionForScope = useCallback((_scopeKey: string) => {
		setLocalSelectedNode(null);
		setNodePanelOpen(false);
		setShowNodeLogs(false);
		setSelectedNodeAssetId(null);
	}, []);

	const executeOperation = useCallback(
		async (operation: WorkflowOperationConfig) => {
			if (!liveWorkflow || operation.disabled) return;
			setOperationLoading(operation.key);
			try {
				await operation.run();
				messageApi.success(`${operation.title}已提交`);
				if (operation.key === "delete") {
					navigate("/pipeline?tab=executions");
					return;
				}
				loadWorkflow();
			} catch (err) {
				messageApi.error(`${operation.title}失败: ${String(err)}`);
			} finally {
				setOperationLoading(null);
			}
		},
		[liveWorkflow, loadWorkflow, messageApi, navigate],
	);

	const runOperation = useCallback(
		(operation: WorkflowOperationConfig) => {
			if (
				operation.key === "delete" ||
				operation.key === "terminate" ||
				operation.key === "resubmit" ||
				operation.key === "retry"
			) {
				setConfirmOperation(operation);
				return;
			}
			executeOperation(operation);
		},
		[executeOperation],
	);
	const handleSelectOverflowOperation = useCallback(
		(
			info: Parameters<NonNullable<MenuProps["onClick"]>>[0] & {
				domEvent?: {
					stopPropagation?: () => void;
				};
			},
		) => {
			const { key, domEvent } = info;
			domEvent?.stopPropagation?.();
			const operation = overflowOperations.find((item) => item.key === key) as
				| WorkflowOperationConfig
				| undefined;
			if (!operation) return;
			runOperation(operation);
		},
		[overflowOperations, runOperation],
	);

	const closeNodeDetailPanel = useCallback(() => {
		setNodePanelOpen(false);
		setShowNodeLogs(false);
		setLocalSelectedNode(null);
		selectNode(null);
		setSelectedNodeAssetId(null);
	}, [selectNode]);

	const handleSelectNode = useCallback(
		(node: WorkflowNodeStatus | null) => {
			const actionableNode = resolveTaskRuntimeNode(node);
			setNodeDetailTab("summary");
			setNodePanelOpen(!!actionableNode);
			setLocalSelectedNode(actionableNode);
			setSelectedNodeAssetId(
				actionableNode && workflowAssetIds.length === 1
					? workflowAssetIds[0]
					: null,
			);
			selectNode(actionableNode);
		},
		[resolveTaskRuntimeNode, selectNode, workflowAssetIds],
	);

	const handleJumpToNodeKey = useCallback(
		(nodeKey?: string) => {
			if (!workflow || !nodeKey) return;
			const normalized = nodeKey.toLowerCase();
			const node = workflow.nodes.find((item) =>
				[
					item.id,
					item.name,
					item.templateName,
					item.displayName,
					item.technicalDisplayName,
				]
					.filter(Boolean)
					.some((value) => value?.toLowerCase() === normalized),
			);
			if (!node) {
				messageApi.warning("未在当前 DAG 中找到对应节点");
				return;
			}
			handleSelectNode(node);
		},
		[handleSelectNode, messageApi, workflow],
	);

	const handleRetryNode = useCallback(
		async (node: WorkflowNodeStatus) => {
			const effectiveRunId = runEventState.run?.id || runId;
			if (!effectiveRunId) {
				messageApi.warning(
					"当前工作流没有关联的 DataBrew 运行，无法重试单个节点",
				);
				return;
			}
			if (node.phase !== "Failed" && node.phase !== "Error") {
				messageApi.warning("只能重试失败或错误节点");
				return;
			}
			setRetryingNodeId(node.id);
			try {
				await retryPipelineRunNode(effectiveRunId, node.id);
				messageApi.success("节点重试已提交");
				loadWorkflow();
				loadRunEvents();
			} catch (err) {
				messageApi.error(`节点重试失败: ${String(err)}`);
			} finally {
				setRetryingNodeId(null);
			}
		},
		[loadRunEvents, loadWorkflow, messageApi, runEventState.run?.id, runId],
	);

	const handleNodeAction = useCallback(
		(node: WorkflowNodeStatus, action: WorkflowDagNodeAction) => {
			const actionableNode = resolveTaskRuntimeNode(node) ?? node;
			if (action === "terminal") {
				setLocalSelectedNode(actionableNode);
				selectNode(actionableNode);
				setNodePanelOpen(false);
				setShowNodeLogs(false);
				setTerminalNode(actionableNode);
				return;
			}
			if (action === "retry") {
				void handleRetryNode(actionableNode);
				return;
			}
			const tabByAction: Partial<
				Record<WorkflowDagNodeAction, WorkflowNodeDetailTabKey>
			> = {
				summary: "summary",
				logs: "logs",
				runtime: "runtime",
				monitoring: "runtime",
			};
			const tab = tabByAction[action];
			if (!tab) return;
			setNodeDetailTab(tab);
			setLocalSelectedNode(actionableNode);
			selectNode(actionableNode);
			if (action === "logs") {
				setNodePanelOpen(false);
				setShowNodeLogs(true);
				return;
			}
			setNodePanelOpen(true);
		},
		[handleRetryNode, resolveTaskRuntimeNode, selectNode],
	);

	const handleSelectEventNode = useCallback(
		(event: PipelineRunEvent) => {
			if (!workflow || event.subjectType !== "node") {
				return;
			}
			const node = workflow.nodes.find((item) => item.id === event.subjectId);
			if (!node) {
				if (taskAssetId && workflow.nodes.length === 1) {
					handleSelectNode(workflow.nodes[0]);
					return;
				}
				messageApi.warning("事件关联的节点不在当前 DAG 中");
				return;
			}
			handleSelectNode(node);
		},
		[handleSelectNode, messageApi, taskAssetId, workflow],
	);

	const handleFilterEvents = useCallback(
		(filters: ReturnType<typeof useWorkflowDetail>["runEventFilters"]) => {
			setRunEventFilters(filters);
		},
		[setRunEventFilters],
	);

	const handleLoadMoreEvents = useCallback(() => {
		if (!runEventState.nextCursor) return;
		loadRunEvents({ append: true, cursor: runEventState.nextCursor });
	}, [loadRunEvents, runEventState.nextCursor]);

	const handleSelectAssetNode = useCallback(
		(row: PipelineRunAssetNode, action: WorkflowDagNodeAction) => {
			if (!workflow) return;
			const node =
				workflow.nodes.find(
					(item) =>
						item.id === row.argoNodeId ||
						item.id === row.pipelineNodeId ||
						item.displayName === row.displayName ||
						item.name === row.displayName,
				) ||
				(row.argoNodeId || row.podName || row.logRef
					? taskRuntimeNodeFromAssetRow(row, workflow.name, taskNodeKey)
					: null);
			if (!node) {
				messageApi.warning("资产节点关联的 DAG 节点暂不可见");
				return;
			}
			const actionableNode =
				node.debug?.logStreamEnabled === false &&
				(row.argoNodeId || row.podName || row.logRef)
					? taskRuntimeNodeFromAssetRow(row, workflow.name, taskNodeKey)
					: node;
			setSelectedNodeAssetId(
				row.assetId && row.assetId !== "no-asset" ? row.assetId : null,
			);
			handleNodeAction(actionableNode, action);
		},
		[handleNodeAction, messageApi, taskNodeKey, workflow],
	);

	const handleShowNodeLogs = useCallback(() => {
		if (!selectedNode) {
			return;
		}
		const actionableNode = resolveTaskRuntimeNode(selectedNode) ?? selectedNode;
		if (!canOpenWorkflowNodeLogs(actionableNode)) {
			messageApi.warning(
				actionableNode.debug?.reason ||
					"当前节点没有绑定实时 Argo 节点，无法打开日志",
			);
			return;
		}
		if (actionableNode.id !== selectedNode.id) {
			setLocalSelectedNode(actionableNode);
			selectNode(actionableNode);
		}
		setShowNodeLogs(true);
	}, [messageApi, resolveTaskRuntimeNode, selectNode, selectedNode]);

	const handleCloseNodeLogs = useCallback(() => {
		setShowNodeLogs(false);
	}, []);

	const handleRetryWorkflow = useCallback(() => {
		if (!workflow) return;
		const retryConfig = operations.find(
			(operation) => operation.key === "retry",
		);
		if (!retryConfig || retryConfig.disabled) {
			messageApi.warning("当前工作流状态不可重试");
			return;
		}
		runOperation(retryConfig);
	}, [messageApi, operations, runOperation, workflow]);

	useEffect(() => {
		if (legacyRoute && name) {
			const search = searchParams.toString().trim();
			navigate(
				`/pipeline/executions/${encodeURIComponent(name)}${search ? `?${search}` : ""}`,
				{
					replace: true,
				},
			);
		}
	}, [legacyRoute, name, navigate, searchParams]);

	useEffect(() => {
		if (!selectedNode) {
			setShowNodeLogs(false);
			setNodePanelOpen(false);
			setSelectedNodeAssetId(null);
		}
	}, [selectedNode]);

	useEffect(() => {
		resetLocalNodeSelectionForScope(nodeSelectionScopeKey);
	}, [nodeSelectionScopeKey, resetLocalNodeSelectionForScope]);

	const failedNodes = useMemo(
		() =>
			workflowNodesForGraph.filter((node) => {
				if (node.phase !== "Failed" && node.phase !== "Error") return false;
				const nodeType = node.type?.toLowerCase();
				if (nodeType === "dag" || nodeType === "steps") return false;
				if ((node.children?.length ?? 0) > 0 && !node.podName) return false;
				return true;
			}),
		[workflowNodesForGraph],
	);
	const workflowCurrentBottleneck = useMemo(() => {
		if (!workflow) return null;
		return getWorkflowCurrentBottleneck(workflowNodesForGraph);
	}, [workflow, workflowNodesForGraph]);
	const selectedNodeSummary = useMemo(() => {
		if (!selectedNode) return undefined;
		const candidates = [
			selectedNode.id,
			selectedNode.name,
			selectedNode.templateName,
			selectedNode.displayName,
			selectedNode.technicalDisplayName,
		]
			.filter((value): value is string => Boolean(value))
			.map((value) => value.toLowerCase());
		return displayRunDetailState.nodeSummary.find((item) =>
			[item.nodeKey, item.nodeName]
				.filter((value): value is string => Boolean(value))
				.some((value) => candidates.includes(value.toLowerCase())),
		);
	}, [displayRunDetailState.nodeSummary, selectedNode]);

	const maxFailureDisplayCount = 3;
	const failedNodeNames = failedNodes.map(
		(node) => node.displayName ?? node.templateName ?? node.name ?? node.id,
	);
	const shownFailedNodeNames = failedNodeNames.slice(0, maxFailureDisplayCount);
	const failureSummaryText = shownFailedNodeNames.length
		? ` ${shownFailedNodeNames.join("、")}`
		: "";
	const moreFailureCount = Math.max(
		0,
		failedNodeNames.length - maxFailureDisplayCount,
	);
	const bottleneckText = workflowCurrentBottleneck
		? `运行当前停在 ${workflowCurrentBottleneck.displayName}`
		: "";
	const hasDatabrewRunContext = Boolean(
		runEventState.run ||
			runEventState.items.length > 0 ||
			displayAssetNodeState.items.length > 0,
	);
	const parentExecutionRunId = parentRunId || runEventState.run?.parentRunId;
	const handleBackToParentOrList = useCallback(() => {
		if (taskAssetId && parentExecutionRunId) {
			navigate(
				buildWorkflowExecutionUrl(parentExecutionRunId, parentExecutionRunId),
			);
			return;
		}
		navigate("/pipeline?tab=executions");
	}, [navigate, parentExecutionRunId, taskAssetId]);
	const handleBackFromLedger = handleBackToParentOrList;

	if (loading && hasDatabrewRunContext && !taskAssetId) {
		return (
			<ExpiredWorkflowLedgerView
				name={name}
				routeRunId={runId}
				parentRunId={parentRunId}
				taskAssetId={taskAssetId}
				taskNodeKey={taskNodeKey}
				runEventState={runEventState}
				runDetailState={runDetailState}
				onBack={handleBackFromLedger}
				alertType="info"
				message="Argo 工作流仍在加载，先展示 DataBrew 运行详情"
				description="实时 DAG、Pod 状态和日志会在工作流接口返回后恢复；当前可先查看 DataBrew 保存的任务清单、节点汇总和失败信息。"
			/>
		);
	}

	if (loading && !workflow) {
		return (
			<div
				style={{
					display: "flex",
					justifyContent: "center",
					padding: 80,
				}}
			>
				<Spin size="large" />
			</div>
		);
	}

	if (!loading && loadError?.kind === "not_found") {
		if (!workflow && (runEventState.run || runEventState.items.length > 0)) {
			const runStatus = runEventState.run?.status;
			const isPending = runStatus === "Pending" || runStatus === "pending";
			return (
				<ExpiredWorkflowLedgerView
					name={name}
					routeRunId={runId}
					parentRunId={parentRunId}
					taskAssetId={taskAssetId}
					taskNodeKey={taskNodeKey}
					runEventState={runEventState}
					runDetailState={runDetailState}
					onBack={handleBackFromLedger}
					alertType={isPending ? "info" : "warning"}
					message={
						isPending
							? "工作流尚未开始执行，正在展示 DataBrew 运行详情"
							: "Argo 工作流暂不可用，正在展示 DataBrew 运行详情"
					}
					description={
						isPending
							? "当前 Pipeline Run 已完成提交，等待调度到执行集群。调度完成后将自动执行，DAG、Pod 状态和实时日志将自动恢复。"
							: "Workflow 可能已被 Argo TTL 清理，DAG、Pod 实时状态和实时日志暂不可用；任务清单、节点汇总和失败信息仍可从 DataBrew 保存的运行结果中查看。"
					}
				/>
			);
		}
		if (!workflow) {
			return <div style={{ padding: 24 }}>未找到工作流</div>;
		}
	}

	if (!loading && loadError?.kind === "error" && !workflow) {
		if (hasDatabrewRunContext && !taskAssetId) {
			return (
				<ExpiredWorkflowLedgerView
					name={name}
					routeRunId={runId}
					parentRunId={parentRunId}
					taskAssetId={taskAssetId}
					taskNodeKey={taskNodeKey}
					runEventState={runEventState}
					runDetailState={runDetailState}
					onBack={handleBackFromLedger}
					alertType="warning"
					message="Argo 工作流暂不可用，正在展示 DataBrew 运行详情"
					description={loadError.message}
				/>
			);
		}
		return (
			<div style={{ padding: 24 }}>
				<Alert
					type="error"
					showIcon
					message="加载工作流失败"
					description={loadError.message}
					action={
						<Button size="small" onClick={loadWorkflow}>
							重试
						</Button>
					}
				/>
			</div>
		);
	}

	if (
		(pendingTaskRouteUsesParentRun || !workflow) &&
		taskAssetId &&
		parentRunId
	) {
		return (
			<ExpiredWorkflowLedgerView
				name={name}
				routeRunId={detailRunId}
				parentRunId={parentRunId}
				taskAssetId={taskAssetId}
				taskNodeKey={taskNodeKey}
				runEventState={runEventState}
				runDetailState={runDetailState}
				onBack={handleBackFromLedger}
				alertType="info"
				message="任务现场尚未提交"
				description="该任务当前没有可用的 child pipeline run 或 Argo workflow 现场。dispatcher 提交 shard 后，日志、Pod 详情和监控入口会在这里恢复；当前先展示父批量运行和冻结任务清单。"
			/>
		);
	}

	if (!workflow) {
		return null;
	}

	const displayableNodeCount = countDisplayableWorkflowNodes(
		workflowNodesForGraph,
	);
	const graphHeight =
		displayableNodeCount <= 1 ? 320 : displayableNodeCount <= 5 ? 420 : 500;
	const databrewRunContextLoading =
		!hasDatabrewRunContext &&
		(runEventState.loading ||
			displayAssetNodeState.loading ||
			costSummaryState.loading);
	const workflowContextRunId = runEventState.run?.id || detailRunId;
	const workflowDisplayTitle =
		workflow.labels?.["databrew/task-display-name"] ||
		(taskAssetId ? `任务 ${taskAssetId}` : workflow.name);
	return (
		<div
			style={{
				height: "calc(100vh - 49px)",
				display: "flex",
				flexDirection: "column",
				width: "100%",
				minWidth: 0,
			}}
		>
			<div
				style={{
					padding: "8px 24px",
					borderBottom: "1px solid #e5e7eb",
					display: "flex",
					alignItems: "center",
					gap: 12,
					flexWrap: "wrap",
				}}
			>
				<Button
					icon={<ArrowLeftOutlined />}
					size="small"
					onClick={handleBackToParentOrList}
				>
					返回
				</Button>
				<h3 style={{ margin: 0, fontSize: 15 }}>{workflowDisplayTitle}</h3>
				{(() => {
					const nodePhases = workflow.nodes
						.filter((n) => n.type !== "DAG")
						.map((n) => n.phase);
					const allTerminal =
						nodePhases.length > 0 &&
						nodePhases.every((p) =>
							["Failed", "Error", "Succeeded", "Skipped", "Omitted"].includes(
								p,
							),
						);
					const hasFailures = failedNodes.length > 0;
					const effectiveColor =
						allTerminal && hasFailures
							? "error"
							: STATUS_COLORS[workflow.status] || "default";
					const effectiveLabel =
						allTerminal && hasFailures && workflow.status === "Running"
							? `${workflow.status}（节点已终止）`
							: workflow.status;
					return <Tag color={effectiveColor}>{effectiveLabel}</Tag>;
				})()}
				{hasDatabrewRunContext ? (
					<Tag color="green">DataBrew 运行</Tag>
				) : databrewRunContextLoading ? (
					<Tag color="blue">同步 DataBrew 运行</Tag>
				) : (
					<Tag color="orange">外部 Workflow</Tag>
				)}
				{workflow.message ? (
					<Tooltip title={workflow.message}>
						<span
							style={{
								color: "#dc2626",
								fontSize: 12,
								maxWidth: 280,
								overflow: "hidden",
								textOverflow: "ellipsis",
								whiteSpace: "nowrap",
							}}
						>
							{workflow.message}
						</span>
					</Tooltip>
				) : null}
				<DurationPanel
					phase={workflow.status}
					startedAt={workflow.createdAt}
					finishedAt={workflow.finishedAt}
					progress={workflow.progress}
				/>
				{failedNodes.length > 0 ? (
					<Alert
						type="error"
						showIcon
						message="检测到失败节点"
						description={
							<div>
								<div>
									<span>
										发现 {failedNodes.length} 个失败/错误节点：
										{failureSummaryText}
									</span>
									{moreFailureCount > 0 ? (
										<span style={{ display: "block" }}>
											以及后续 {moreFailureCount} 个失败节点
										</span>
									) : null}
								</div>
							</div>
						}
						style={{
							maxWidth: 560,
							marginRight: 12,
						}}
					/>
				) : null}
				{workflowCurrentBottleneck ? (
					<Alert
						type="warning"
						showIcon
						message="当前卡点"
						description={
							<div>
								<div style={{ marginBottom: 2 }}>{bottleneckText}</div>
								{workflowCurrentBottleneck.subStatus ? (
									<div style={{ color: "#0369a1" }}>
										子状态：{workflowCurrentBottleneck.subStatus}
									</div>
								) : null}
								{workflowCurrentBottleneck.node.message ? (
									<div
										style={{
											color: "#475569",
											marginTop: 4,
											whiteSpace: "pre-wrap",
										}}
									>
										{workflowCurrentBottleneck.node.message}
									</div>
								) : null}
								<div style={{ marginTop: 6 }}>
									<Button
										size="small"
										type="link"
										onClick={() =>
											handleSelectNode(workflowCurrentBottleneck.node)
										}
									>
										跳转节点明细
									</Button>
								</div>
							</div>
						}
						style={{
							maxWidth: 560,
							marginRight: 12,
						}}
					/>
				) : null}
				{statusSyncWarning ? (
					<Alert
						type="warning"
						showIcon
						message="状态同步告警"
						description={statusSyncWarning}
						style={{
							maxWidth: 520,
							marginRight: 12,
						}}
					/>
				) : null}
				{loadError?.kind === "error" ? (
					<Alert
						type="warning"
						showIcon
						message="实时工作流刷新失败，已保留当前页面"
						description={loadError.message}
						action={
							<Button size="small" onClick={loadWorkflow}>
								重试
							</Button>
						}
						style={{
							maxWidth: 560,
							marginRight: 12,
						}}
					/>
				) : null}
				{costSummaryState.item &&
				typeof costSummaryState.item.totalEstimatedCostUsd === "number" ? (
					<Tooltip title="估算成本，非 GCP Billing 最终账单">
						<Tag color="blue">
							~${costSummaryState.item.totalEstimatedCostUsd?.toFixed(4)}
						</Tag>
					</Tooltip>
				) : null}
				<div
					style={{
						marginLeft: "auto",
						display: "flex",
						alignItems: "center",
						gap: 8,
					}}
				>
					<Space size={4} wrap>
						{quickOperations.map((operation) => (
							<Tooltip
								key={operation.key}
								title={
									operation.description ||
									(operation.key === "resubmit"
										? "基于当前运行配置重新提交一次新的执行。"
										: undefined)
								}
							>
								<Button
									size="small"
									icon={operation.icon}
									danger={operation.danger}
									loading={operationLoading === operation.key}
									onClick={() => runOperation(operation)}
								>
									{operation.title}
								</Button>
							</Tooltip>
						))}
						{overflowOperationItems.length > 0 ? (
							<Dropdown
								menu={{
									items: overflowOperationItems,
									onClick: (info) => handleSelectOverflowOperation(info),
								}}
								trigger={["click"]}
							>
								<Button
									size="small"
									icon={<MoreOutlined />}
									loading={overflowOperations.some(
										(operation) => operationLoading === operation.key,
									)}
								>
									更多操作
								</Button>
							</Dropdown>
						) : null}
					</Space>
					<Segmented
						value={viewMode}
						onChange={(val) => setViewMode(val as "dag" | "timeline")}
						options={[
							{
								label: (
									<>
										<ApartmentOutlined /> DAG
									</>
								),
								value: "dag",
							},
							{
								label: (
									<>
										<BarsOutlined /> 时间线
									</>
								),
								value: "timeline",
							},
						]}
					/>
				</div>
			</div>
			<WorkflowSummaryCards
				workflow={workflow}
				runEventState={displayRunEventState}
				costSummaryState={costSummaryState}
				runDetailState={displayRunDetailState}
			/>
			<CurrentRunBlockerCard
				blocker={displayRunDetailState.blocker}
				loading={displayRunDetailState.loading}
				error={displayRunDetailState.error}
				onJumpToNode={handleJumpToNodeKey}
			/>
			<div
				style={{
					flex: 1,
					minHeight: 0,
					minWidth: 0,
					overflowY: "auto",
					background: "#f8fafc",
					paddingTop: 12,
				}}
			>
				<div
					style={{
						height: graphHeight,
						margin: "0 24px 12px",
						border: "1px solid #dbe3ee",
						borderRadius: 8,
						overflow: "hidden",
						background: "#eef2f6",
					}}
				>
					{viewMode === "dag" ? (
						<WorkflowDagView
							nodes={workflowNodesForGraph}
							workflowEdges={workflow.edges}
							nodeSummaries={displayRunDetailState.nodeSummary}
							selectedNodeId={selectedNode?.id ?? null}
							onNodeSelect={handleSelectNode}
							onNodeAction={handleNodeAction}
							emptyMessage={workflow.message}
							workflowStatus={workflow.status}
						/>
					) : (
						<WorkflowTimelineView
							nodes={workflowNodesForGraph}
							selectedNodeId={selectedNode?.id ?? null}
							onNodeSelect={handleSelectNode}
						/>
					)}
				</div>
				{hasDatabrewRunContext || databrewRunContextLoading ? (
					<WorkflowAssetNodePanel
						assetNodeState={displayAssetNodeState}
						costSummaryState={costSummaryState}
						runAssetIds={workflowAssetIds}
						workflowNodeCount={displayableNodeCount}
						workflowNodes={workflowNodesForGraph}
						onSelectAssetNode={handleSelectAssetNode}
					/>
				) : (
					<div style={{ padding: "12px 24px" }}>
						<Alert
							type="info"
							showIcon
							message="暂无资产节点明细"
							description="此工作流不是由 DataBrew 部署，没有资产绑定信息。仍可使用 DAG、Pod 日志和终端调试。"
						/>
					</div>
				)}
				<WorkflowRunContextPanel
					runEventState={runEventState}
					runEventFilters={runEventFilters}
					onFilterEvents={handleFilterEvents}
					onRefreshEvents={loadRunEvents}
					onLoadMoreEvents={handleLoadMoreEvents}
					onSelectNodeEvent={handleSelectEventNode}
				/>
			</div>

			<WorkflowNodeDetailPanel
				node={selectedNode}
				workflow={workflow}
				runId={workflowContextRunId}
				fallbackAssetId={selectedNodeAssetId || undefined}
				nodeSummary={selectedNodeSummary}
				failureSummary={displayRunDetailState.failureSummary}
				open={nodePanelOpen}
				onClose={closeNodeDetailPanel}
				canRetryWorkflow={
					canRetryWorkflow ||
					!!(
						selectedNode &&
						(selectedNode.phase === "Failed" ||
							selectedNode.phase === "Error") &&
						(runEventState.run?.id || runId)
					)
				}
				onRetryWorkflow={
					selectedNode &&
					(selectedNode.phase === "Failed" || selectedNode.phase === "Error") &&
					(runEventState.run?.id || runId)
						? () => handleRetryNode(selectedNode)
						: handleRetryWorkflow
				}
				retryWorkflowLoading={
					selectedNode ? retryingNodeId === selectedNode.id : false
				}
				retryWorkflowLabel={
					selectedNode &&
					(selectedNode.phase === "Failed" || selectedNode.phase === "Error") &&
					(runEventState.run?.id || runId)
						? "重试节点"
						: "重试工作流"
				}
				onShowLogs={handleShowNodeLogs}
				activeTab={nodeDetailTab}
				onActiveTabChange={setNodeDetailTab}
			/>

			{terminalNode ? (
				<Suspense fallback={null}>
					<WorkflowPodTerminalDrawer
						open={!!terminalNode}
						workflowName={workflow.name}
						runId={workflowContextRunId}
						node={terminalNode}
						onClose={() => setTerminalNode(null)}
					/>
				</Suspense>
			) : null}

			<Modal
				open={!!confirmOperation}
				title={
					confirmOperation
						? `确认${confirmOperation.title} ${workflow.name}?`
						: ""
				}
				okText={confirmOperation?.title}
				cancelText="取消"
				okButtonProps={{ danger: confirmOperation?.danger }}
				onOk={async () => {
					if (!confirmOperation) return;
					const operation = confirmOperation;
					setConfirmOperation(null);
					await executeOperation(operation);
				}}
				onCancel={() => setConfirmOperation(null)}
			>
				{confirmOperation ? (
					<Typography.Paragraph style={{ margin: 0 }}>
						{confirmOperation.description ??
							`确认执行 ${confirmOperation.title}，请确认当前运行上下文允许该操作。`}
					</Typography.Paragraph>
				) : null}
			</Modal>

			<Modal
				open={showNodeLogs}
				title={
					selectedNode
						? `${selectedNode.displayName || selectedNode.name} 日志`
						: "日志"
				}
				width="80%"
				onCancel={handleCloseNodeLogs}
				footer={null}
				style={{ top: 32 }}
				styles={{ body: { height: "calc(100vh - 180px)", padding: 0 } }}
			>
				<WorkflowLogPanel
					selectedNode={selectedNode}
					loading={logState.loading}
					logContent={logState.content}
					error={logState.error}
					search={logState.search}
					following={logState.following}
					followStatus={logState.followStatus}
					followMessage={logState.followMessage}
					logResponse={logState.response}
					clientTruncated={logState.clientTruncated}
					onSearch={setLogSearch}
					onFollow={startFollowLogs}
					onStop={stopFollowLogs}
					onDownload={downloadLogs}
				/>
			</Modal>
		</div>
	);
}
